import { createApp } from "vue";
import App from "./App.vue";
import appUse from "./common/utils/app_use";
import "./common/styles/common.less";
import "./common/styles/global.less";
// import "./common/utils/flexible.js";
import store from "./store";
//获取后台配置
await store.dispatch("GetConfig");
import i18n from "./locale/index";
import mitt from "mitt";
import defaultImage from "@/assets/images/default.gif";
import errImage from "@/assets/images/err.png";
//引入图片懒加载插件
import Lazyload from "vue3-lazyload";
import router from "./router";
let app = null;
app = createApp(App);
//注册插件
app.use(router);
app.use(store);
app.use(i18n);
app.use(Lazyload, {
  loading: defaultImage, //可以指定加载中的图像
  error: errImage, //可以指定加载失败的图像
});
window.$t = i18n.global.t;
window.$Bus = mitt();
appUse(app);
app.mount("#app");
