<template>
    <div class="content flex justify-center align-center">
        <div class="chat-box flex">
            <EasySpin :spinning="spinning" :tip="tip" />
            <div class="user-box">
                <SwitchRoles />
                <UserList ref="userList" @userItemClick="userItemClick" />
            </div>
            <div class="room">
                <ChatRoom ref="chatRoomRef" @actionsCallBack="actionsCallBack" />
            </div>
        </div>
    </div>
</template>

<script setup>
import { defineComponent, reactive, ref, getCurrentInstance, computed, onMounted, toRefs, onBeforeUnmount } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useStore } from 'vuex'
import UserList from '@/views/Chat/components/UserList'
import ChatRoom from '@/views/Chat/components/ChatRoom'
import SwitchRoles from '@/views/Chat/components/SwitchRoles'
import { useSocket } from '@/common/utils/useSocket'
import utils from '@/common/utils/utils'
const router = useRouter()
const route = useRoute()
const store = useStore()
const state = reactive({
    spinning: false,
    tip: '',
    chatRoomRef: null,
    userList: null,
    wsUrl: '', //ws://192.168.0.95:8282
    mainMessage: null,
})
const { spinning, tip, chatRoomRef, userList } = toRefs(state)

onMounted(() => {
    //监听全局事件
    window.$Bus.on('chatRoomCallBack', chatRoomCallBack)
})

//页面销毁时清除监听器
onBeforeUnmount(() => {
    window.$Bus.off('chatRoomCallBack', chatRoomCallBack)
})

const login = async () => {
    if (route.query.username) {
        await store.dispatch('login', route.query).then((res) => {
            if (res.role == 'user') {
                router.replace('/errorPage?status=403')
                return
            }
            window.$message.success(window.$t('登陆成功'))
            state.wsUrl = res.wss
            res && initUseSocket(res)
            res && userList.value?.loadingPage(res)
        })
    }
}
login()

//聊天房间事件
const chatRoomCallBack = (res) => {
    switch (res.type) {
        case 'uploadFile':
            state.spinning = res.data
            state.tip = window.$t('上传中')
            break
        case 'transferKf':
            //成功转接客服的回调，重置窗口
            userList.value?.loadingPage(store.state.user.userInfo)
            userList.value?.setChatListIndex()
            break
        default:
            break
    }
}
//会话列表item点击事件
const userItemClick = (res) => {
    chatRoomRef.value?.loadingRoom(res)
}

//创建Socket连接
const initUseSocket = async (userInfo) => {
    state.mainMessage = window.$message.loading('连接中，请稍等...', 0)
    const useSocketData = useSocket(state.wsUrl, {
        heartbeatParams: JSON.stringify({
            msg_type: 'ping',
        }),
    })
    utils.setUseSocket(useSocketData)
    useSocketData.on('open', async (event) => {
        // console.log('已连接到服务器', event)
        let params = {
            msg_type: 'bind',
            from_id: userInfo.username,
            token: userInfo.token,
        }
        useSocketData.send(JSON.stringify(params))
    })
    useSocketData.on('message', async (data) => {
        let res = ''
        //接收消息的处理逻辑
        if (data && utils.jsonString(data)) {
            res = JSON.parse(data)

            //绑定成功
            if (res.msg_type == 'bind') {
                await utils.sleep(150)
                setTimeout(state.mainMessage, 0)
                window.$Bus.emit('updateSpin', { flag: false, tip: '' })
                window.$message.success(window.$t('连接成功'))
                chatRoomRef.value?.updateOpenSocket(true)
            }

            if (res.msg_type == 'ping') {
                return
            }

            //聊天房间的回调
            chatRoomRef.value?.messageEvent(data)
        }
    })
    useSocketData.on('error', (error) => {
        // console.error('WebSocket错误：', error)
    })
    useSocketData.on('close', (event) => {
        if (useSocketData.socket.reconnectAttempts < useSocketData.socket.opts.maxReconnectAttempts) {
            window.$message.error(window.$t('连接中断，正在尝试重新连接'))
        } else {
            window.$message.error(window.$t('连接异常，已停止重连'))
        }
        window.$Bus.emit('updateSpin', { flag: false, tip: '' })
        setTimeout(state.mainMessage, 0)
        chatRoomRef.value?.updateOpenSocket(false)
        // console.log('连接已关闭', event)
    })
    useSocketData.on('reconnect', (event) => {
        state.mainMessage = window.$message.loading('重新连接中，请稍等...', 0)
        // console.log('重新连接中', event)
    })
    //重新连接次数已用完end
    useSocketData.on('reconnectEnd', (event) => {
        window.$Modal.info({
            title: window.$t('温馨提示'),
            content: window.$t('尝试多次连接后依旧失败，请稍等片刻后重新进入页面'),
            onOk() {
                console.log('ok')
            },
        })
    })
}

const actionsCallBack = (type, res) => {
    switch (type) {
        case 'messageEvent':
            // 回显到会话列表中
            userList.value?.updateMessage(res)
            break

        default:
            break
    }
}
</script>
<style lang="less" scoped>
.content {
    width: 100%;
    height: 100vh;
    background: #fafafa;
    background-image: url('@/assets/images/bg.png');
    background-size: 100% 100%;
    background-repeat: no-repeat;
}
.chat-box {
    min-width: 1200px;
    max-width: 1260px;
    height: 90vh;
    background-color: #f0f0f0;
    overflow: hidden;
    border-radius: 2px;
    position: relative;
    .user-box {
        min-width: 270px;
        height: 100%;
        box-sizing: border-box;
        border: 1px solid #d0d0d0;
        border-right: 0;
        display: flex;
    }
    .room {
        flex: 1;
        height: 100%;
        box-sizing: border-box;
        border: 1px solid #d0d0d0;
    }
}
</style>