<template>
    <!-- 客户信息 -->
    <a-drawer :mask="true" placement="right" :closable="false" v-model:open="showDrawer" :get-container="false" :style="{ position: 'absolute',overflow:'hidden' }">
        <div class="user-info">
            <EasySpin :spinning="easySpinning" />
            <div class="drawer-header flex justify-center">
                <div class="item" :class="navIndex === index?'active':''" v-for="(item,index) in navList" :key="item.value" @click="navClick(item,index)">{{item.name}}</div>
            </div>
            <template v-if="navIndex == 0 && toUserInfo">
                <div class="title flex align-center">
                    <img class="avatar mr-10" v-lazy="toUserInfo.avatar" />
                    <span class="name">{{toUserInfo.nickname}}</span>
                </div>
                <div class="border"></div>
                <div class="pl-15 pr-15">
                    <div class="desc flex align-center justify-between cursor-pointer" v-for="(item,index) in toUserInfo.extends" :key="index" @click="goUrl(item.url)">
                        <span class="name">{{item.name}}</span>
                        <span class="value">{{item.value}}</span>
                    </div>
                    <!-- <div class="pay-statistics">
                        <div class="title">{{$t('交易统计')}}</div>
                        <div class="flex">
                            <div class="item">
                                <div class="title">{{$t('近期下单时间')}}</div>
                                <div class="value">2015/05/12</div>
                            </div>
                            <div class="item-line"></div>
                            <div class="item">
                                <div class="title">{{$t('累计消费金额(元)')}}</div>
                                <div class="value">0.00</div>
                            </div>
                            <div class="item-line"></div>
                            <div class="item">
                                <div class="title">{{$t('累计下单数')}}</div>
                                <div class="value">0.00</div>
                            </div>
                        </div>
                    </div>-->
                </div>
            </template>
            <template v-else>
                <div class="search-box">
                    <a-input v-model:value="chatRecordParams.keyword" :placeholder="$t('请输入关键字')" @keyup="handleKeyUp">
                        <template #prefix>
                            <SearchOutlined style="color:#B8B8BC" />
                        </template>
                    </a-input>
                </div>
                <div class="history-message scrollbar" @scroll="chatScroll" ref="chatScrollRef">
                    <div class="more flex align-center justify-center fs-14 mt-10" v-if="messageList.length >= 10">
                        <Loadmore :status="loadStatus" />
                    </div>
                    <!-- 聊天消息的item -->
                    <template v-if="messageList.length > 0">
                        <MessageItem mode="history" :item="item" v-for="item in messageList" :key="item.id" :toUserInfo="toUserInfo" :isChatScrollMoreEvent="chatScrollMoreEvent" />
                    </template>
                    <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                        <a-empty :description="$t('暂无聊天记录')" :image="simpleImage" />
                    </div>
                </div>
            </template>
        </div>
    </a-drawer>
</template>

<script setup>
import { defineComponent, reactive, ref, getCurrentInstance, computed, onMounted, toRefs, nextTick } from 'vue'
import { SearchOutlined } from '@ant-design/icons-vue'
import MessageItem from '@/views/Chat/components/MessageItem'
import utils from '@/common/utils/utils'
import dayjs from 'dayjs'
import { Empty } from 'ant-design-vue'
import $ from 'jquery'
import { useStore } from 'vuex'
const store = useStore()
const simpleImage = Empty.PRESENTED_IMAGE_SIMPLE
const emits = defineEmits(['actionEvent'])
const state = reactive({
    navList: [
        {
            name: window.$t('客户信息'),
            value: 1,
        },
        {
            name: window.$t('聊天记录'),
            value: 2,
        },
    ],
    navIndex: 0,
    showDrawer: false,
    messageList: [],
    //聊天记录接口参数
    chatRecordParams: {
        keyword: '', //关键词检索
        page: 1, //页码
        pageSize: 10, //条数
        toUser: '',
    },
    loadStatus: 'loadmore', //加载更多
    easySpinning: false,
    chatScrollRef: null,
    toUserInfo: null,
    chatScrollMoreEvent: false, //是否为滚动到顶部触发事件
})
const {
    navList,
    navIndex,
    showDrawer,
    messageList,
    easySpinning,
    loadStatus,
    chatScrollRef,
    toUserInfo,
    chatRecordParams,
    chatScrollMoreEvent,
} = toRefs(state)

//获取客户聊天记录
const getChatRecord = async (flag = false) => {
    let scrollHeight = chatScrollRef.value?.scrollHeight || 0
    let newScrollHeight = 0
    if (!flag) {
        state.easySpinning = true
    }
    state.loadStatus = 'loading'
    window.$request
        .post('/im/User/getChatRecord', state.chatRecordParams)
        .then((res) => {
            let newData = res
                .map((v) => {
                    if (v.msg_type == 'text') {
                        v.msg_body.text = utils.initMessage(v.msg_body.text)
                    }
                    if (v.create_time) {
                        v.history_date = formattedTime(v.create_time)
                    }
                    return v
                })
                .reverse()

            state.messageList = [...newData, ...state.messageList]

            // 使用一个 Set 来追踪已经出现过的 history_date
            let seenDates = new Set()

            // 遍历数组，处理重复的 history_date
            state.messageList.forEach((message, index) => {
                if (seenDates.has(message.history_date)) {
                    // 如果这个 history_date 已经出现过，则将其赋值为空字符串
                    state.messageList[index].history_date = ''
                } else {
                    // 否则，将这个 history_date 添加到 Set 中
                    seenDates.add(message.history_date)
                }
            })

            if (res.length < 10) {
                state.loadStatus = 'nomore'
            } else {
                state.loadStatus = 'loadmore'
            }
            //无缝衔接滚动条高度，实现往前面插入元素后滚动条置顶问题
            nextTick(() => {
                newScrollHeight = chatScrollRef.value?.scrollHeight || 0
                if (flag) {
                    state.chatScrollMoreEvent = true
                    initScroll(0, newScrollHeight - scrollHeight)
                } else {
                    state.chatScrollMoreEvent = false
                    initScroll(0)
                }
            })
            state.easySpinning = false
        })
        .catch((err) => {
            state.easySpinning = false
        })
}
const formattedTime = (item) => {
    const now = dayjs() // 当前时间
    const time = dayjs.unix(item) // 时间戳对应的时间
    if (now.year() !== time.year()) {
        return time.format('YYYY-MM-DD') // 如果不是今年，显示年月日
    } else {
        return time.format('MM-DD') // 其他情况显示月日
    }
}
//客户信息导航切换
const navClick = (item, index) => {
    state.navIndex = index
    if (item.value == 2) {
        searchChatRecord()
    }
}
const open = (to_user_info) => {
    state.navIndex = 0
    state.chatRecordParams.toUser = to_user_info.username
    state.showDrawer = !state.showDrawer
    getUserInfo(state.chatRecordParams.toUser)
}
const close = () => {
    state.showDrawer = false
}
//搜索
const handleKeyUp = (event) => {
    if (event.key === 'Enter') {
        searchChatRecord()
    }
}
//聊天列表数据
const searchChatRecord = () => {
    state.chatRecordParams.page = 1
    state.messageList = []
    getChatRecord()
}
//加载更多
const chatScroll = (e) => {
    if (e.target.scrollTop == 0) {
        if (state.loadStatus != 'nomore' && state.loadStatus != 'loading') {
            state.chatRecordParams.page++
            getChatRecord(true)
        }
    }
}
//回滚滚动条
const initScroll = (time = 300, scrollTop = null) => {
    nextTick(() => {
        $('.history-message').animate({ scrollTop: scrollTop != null ? scrollTop : $('.history-message')[0].scrollHeight }, time) // 使用 animate() 函数实现平滑滚动效果
    })
}
const getUserInfo = (username) => {
    state.easySpinning = true
    store
        .dispatch('getApiUserInfo', username)
        .then((res) => {
            state.toUserInfo = res
            state.easySpinning = false
        })
        .catch((err) => {
            state.easySpinning = false
        })
}
const goUrl = (url) => {
    if (url) {
        location.href = url
    }
}
defineExpose({ open, close })
</script>
<style lang="less" scoped>
.user-info {
    width: 100%;
    height: 100%;
    overflow: hidden;
    .drawer-header {
        justify-content: space-around;
        border-bottom: 1px solid #e2e2e2;
        padding: 14px;
        .item {
            font-weight: 400;
            font-size: 14px;
            color: #333333;
            padding: 6px 10px;
            cursor: pointer;
            user-select: none;
            &.active {
                background-color: var(--primary-color);
                color: #fff;
            }
        }
    }
    .title {
        padding: 15px;
        .name {
            font-weight: 500;
            font-size: 16px;
            color: #333333;
        }
        .avatar {
            width: 50px;
            height: 50px;
            border-radius: 6px;
        }
    }
    .border {
        width: 100%;
        height: 8px;
        background: #e8e8e8;
        border-radius: 0px 0px 0px 0px;
    }
    .desc {
        height: 44px;
        border-bottom: 1px solid rgba(0, 0, 0, 0.05);
        font-weight: 400;
        font-size: 14px;
        .name {
            color: #3d3d3d;
        }
        .value {
            color: #888888;
        }
    }
    .pay-statistics {
        margin: 10px 0;
        .title {
            padding: 0;
            font-weight: 400;
            font-size: 18px;
            color: #3d3d3d;
            margin-bottom: 10px;
        }
        .item {
            flex: 1;
            text-align: left;
            .title {
                font-weight: 400;
                font-size: 12px;
                color: #333333;
                margin-bottom: 5px;
            }
            .value {
                color: #888888;
            }
        }
        .item-line {
            width: 1px;
            height: 40px;
            display: inline-block;
            border-right: 1px solid #d0d0d0;
            margin: 0 10px;
        }
    }

    .search-box {
        padding: 16px;
        border-bottom: 1px solid #e2e2e2;
        .ant-input-affix-wrapper {
            border-radius: 20px;
        }
    }
    .history-message {
        padding: 0 15px;
        height: calc(100% - 125px);
        box-sizing: border-box;
        overflow: hidden;
        overflow-y: auto;
        padding-bottom: 10px;
        .more {
            color: #333;
            text-align: center;
            user-select: none;
            height: 26px;
            font-size: 12px;
        }
        .message-content {
            margin-top: 0px;
            margin-bottom: 40px;
            &:last-child {
                margin-bottom: 0;
            }
        }
    }
}
.rootClassName {
    overflow: hidden !important;
}
</style>