<template>
    <a-config-provider :theme="defaultTheme" :locale="locale">
        <EasySpin :spinning="easySpinning" :tip="tip" />
        <router-view></router-view>
    </a-config-provider>
</template>

<script>
import { reactive, toRefs, ref, computed, getCurrentInstance, onBeforeUnmount, onMounted } from 'vue'
import langList from './locale/lang/antDesignVueLang'
import utils from '@/common/utils/utils'
import { useStore } from 'vuex'
import { useRoute, useRouter } from 'vue-router'
export default {
    name: 'App',
    setup() {
        const store = useStore()
        const route = useRoute()
        const state = reactive({
            defaultTheme: {
                token: {
                    colorPrimary: '#4EAC60',
                },
            },
            locale: langList[utils.getLang()],
            easySpinning: false,
            tip: window.$t('加载中...'),
        })
        const getConfig = computed(() => {
            return store.state.user ? store.state.user.config : null
        })
        if (getConfig.value) {
            state.defaultTheme.token.colorPrimary = getConfig.value.main_color
        }
        //方法
        const languageChange = (e) => {
            const { lang } = e
            state.locale = langList[lang]
        }
        const updateSpin = (params) => {
            state.easySpinning = params.flag
            if (params.tip) {
                state.tip = params.tip
            }
        }

        //监听全局事件
        window.$Bus.on('languageChange', languageChange)
        window.$Bus.on('updateSpin', updateSpin)
        //页面销毁时清除监听器
        onBeforeUnmount(() => {
            window.$Bus.off('languageChange', languageChange)
            window.$Bus.off('updateSpin', updateSpin)
        })
        onMounted(async () => {})
        return { ...toRefs(state) }
    },
}
</script>

<style lang="less">
body {
    overflow: hidden;
}
#app {
    min-width: 1200px; //最小屏幕宽度为1280px
}
.main-width {
    max-width: 1200px; //最小屏幕宽度为1280px
    box-sizing: border-box;
}
</style>
