<template>
    <div class="chat-room">
        <EasySpin :spinning="easySpinning" :tip="spinTip" />
        <div v-if="toUserInfo" style="height:100%">
            <div class="header flex justify-between align-center">
                <div class="name">{{toUserInfo.nickname || '--'}}</div>
                <div class="btn cursor-pointer" @click="showMessageInfo">
                    <EllipsisOutlined :style="{fontSize:'26px',color: '#666'}" />
                </div>
            </div>
            <div class="chat-room-section">
                <div class="chat-message scrollbar" @scroll="chatScroll" ref="chatScrollRef">
                    <div class="more flex align-center justify-center fs-14" v-if="messageList.length >= chatRecordParams.pageSize">
                        <Loadmore :status="loadStatus" />
                    </div>
                    <!-- 聊天消息的item -->
                    <MessageItem
                        :isChatScrollMoreEvent="chatScrollMoreEvent"
                        :item="item"
                        v-for="item in messageList"
                        :key="item.msg_id"
                        @videoLoaded="videoLoaded"
                        @resendMessage="resendMessage"
                        @msgItemMenuClick="msgItemMenuClick"
                        :toUserInfo="toUserInfo"
                    />
                </div>
                <div class="footer" :class="{'disable':!isOpenSocket}">
                    <div class="loading" v-if="!isOpenSocket">{{$t('等待连接成功')}}</div>
                    <MessageFooterActions @actionsCallBack="actionsCallBack" :toUserInfo="toUserInfo" />
                    <div class="input-message mt-5 mb-5 scrollbar" :contenteditable="isOpenSocket" @keydown="handleKeyDown" @blur="handleBlur" :placeholder="$t('请输入消息，按Enter键 或 点击发送按钮发送')"></div>
                    <div class="flex justify-end">
                        <a-tooltip placement="top" v-model:open="sendTip" trigger="contextmenu">
                            <template #title>
                                <span>{{$t('不能发送空白信息')}}</span>
                            </template>
                            <div class="send-btn flex align-center justify-center" @click="sendMessage">{{$t('发送')}}</div>
                        </a-tooltip>
                    </div>
                </div>
                <!-- 客户信息 -->
                <ChatRoomInfo ref="chatRoomInfo" />
            </div>
        </div>
        <div class="flex align-center justify-center" style="width: 100%;height: 100%;">
            <a-empty :description="$t('暂无会话')" :image="simpleImage" />
        </div>
    </div>
</template>

<script setup>
import { defineComponent, reactive, ref, getCurrentInstance, computed, onMounted, toRefs, nextTick, watch, onBeforeUnmount } from 'vue'
import { EllipsisOutlined } from '@ant-design/icons-vue'
import MessageItem from '@/views/Chat/components/MessageItem'
import ChatRoomInfo from '@/views/Chat/components/ChatRoomInfo'
import MessageFooterActions from '@/views/Chat/components/MessageFooterActions'
import emojiJSON from '@/common/utils/emoji.json'
import $ from 'jquery'
import { Empty } from 'ant-design-vue'
import utils from '@/common/utils/utils'
import debounce from '@/common/utils/debounce'
import dayjs from 'dayjs'
import { cloneDeep } from 'lodash'
import { useStore } from 'vuex'
const store = useStore()
const simpleImage = Empty.PRESENTED_IMAGE_SIMPLE
const emits = defineEmits(['actionsCallBack'])
let inputMessage = null
let observer = null
const state = reactive({
    easySpinning: false,
    spinTip: window.$t('加载中...'),
    sendTip: false,
    sendTipTimeout: null,
    message: '',
    chatRoomInfo: null,
    username: '',
    messageList: [],
    //聊天记录接口参数
    chatRecordParams: {
        keyword: '', //关键词检索
        page: 1, //页码
        pageSize: 20, //条数
        toUser: '',
    },
    toUserInfo: null,
    userInfo: '',
    isOpenSocket: false, //是否成功连接Socket
    loadStatus: 'loadmore', //加载更多
    chatScrollRef: null,
    chatScrollMoreEvent: false, //是否为滚动到顶部触发事件
    chatId: '', //房间id
    readList: [], //上报的消息列表
})
const {
    messageList,
    message,
    sendTip,
    chatRoomInfo,
    easySpinning,
    username,
    spinTip,
    toUserInfo,
    loadStatus,
    chatScrollRef,
    chatScrollMoreEvent,
    isOpenSocket,
    chatId,
    chatRecordParams,
} = toRefs(state)

onMounted(() => {
    state.messageList = state.messageList.map((v) => {
        v.content = utils.initMessage(v.content)
        return v
    })
    // nextTick(() => {
    //     initIntersectionObserver()
    // })
})

// 在组件销毁之前移除监听器
onBeforeUnmount(() => {
    if (observer) {
        observer.disconnect() // 断开 Intersection Observer 的连接
    }
})

//文本域键盘事件
const handleKeyDown = (event) => {
    if (event.ctrlKey && event.key === 'Enter') {
        event.preventDefault() // 阻止默认行为
        const div = document.createElement('div') // 创建一个 <div> 元素
        div.setAttribute('data-type', 'br') // 添加自定义属性
        const br = document.createElement('br') // 创建一个 <br> 元素
        div.appendChild(br) // 将 <br> 元素添加到 <div> 中
        const selection = window.getSelection()
        if (selection.rangeCount > 0) {
            const range = selection.getRangeAt(0)
            range.deleteContents() // 删除当前选区内容（如果有）
            range.insertNode(div) // 插入换行符
            range.setStartAfter(div) // 将光标移到换行符之后
            range.collapse(true) // 折叠选区
            selection.removeAllRanges() // 清除所有选区
            selection.addRange(range) // 添加新的选区
        }
        // 等待 DOM 更新后滚动到底部
        nextTick(() => {
            inputMessage.scrollTop = inputMessage.scrollHeight
        })
        return
    }
    if (event.key === 'Enter') {
        // 在这里执行按下Enter时的操作
        event.preventDefault() // 阻止默认的回车换行行为
        sendMessage()
    }
    //回退事件
    if (event.key === 'Enter') {
    }
}
const handleBlur = () => {}

const sendMessage = () => {
    //没连接上ws就不给操作
    if (!state.isOpenSocket) {
        return
    }
    const div = document.createElement('div') // 创建一个 <div> 元素
    div.innerHTML = inputMessage.innerHTML
    // 使用正则表达式进行替换
    function replaceNestedDivs(html) {
        // 定义正则表达式以匹配 <div data-type="br">...</div> 标签，并捕获其中的内容和 <img> 标签（如果有的话）
        const regex = /<div\s+data-type="br">(.*?)(<img[^>]*>)?/gi

        // 使用替换函数对匹配到的内容进行处理
        return html.replace(regex, function (match, p1, p2) {
            const content = p1 ? p1.trim() : '' // 去除捕获文本内容的前后空格
            const imgTag = p2 ? ` ${p2}` : '' // 如果捕获的 <img> 标签存在，则返回空格加上该标签
            // 返回处理后的内容和 <img> 标签
            return `\n${content}${imgTag}`
        })
    }
    div.innerHTML = replaceNestedDivs(div.innerHTML)
    div.innerHTML = div.innerHTML.replace(/<img\s+data-code="([^"]+)"[^>]*>/g, '$1')
    state.message = div.innerText
    // 如果文本内容不为空，则执行提交操作
    if (state.message) {
        sendMessageFun('text', state.message)
    } else {
        if (state.sendTipTimeout) {
            return
        }
        state.sendTip = true
        state.message = ''
        inputMessage.innerHTML = ''
        state.sendTipTimeout = setTimeout(() => {
            state.sendTip = false
            state.sendTipTimeout = null
        }, 1500)
    }
}

//发送消息的封装方法
const sendMessageFun = (msg_type, value) => {
    let params = {
        msg_type: msg_type,
        from_id: state.userInfo ? state.userInfo.username : '',
        target_id: state.chatRecordParams.toUser,
        msg_body: {},
        msg_id: 'pc_' + utils.guid(11, false, 10),
        send_status: 'loading',
        chat_id: state.chatId,
        is_read: 0,
    }
    switch (msg_type) {
        case 'text':
            params.msg_body.text = utils.initMessage(value)
            break
        case 'image':
            params.msg_body.url = value.url
            break
        case 'video':
            params.msg_body.url = value.url
            params.msg_body.thunm = value.thunm
            break
        case 'kf_coupon':
            params.msg_body = value.coupon
            break
        case 'recommend_goods':
            params.msg_body = value.goods
            break
        case 'resendMessage':
            params = value
            params.send_status = 'loading'
            break
        case 'withdraw':
            params = value
            break

        default:
            break
    }
    //断开连接的情况下发送任何东西都是error状态
    if (!state.isOpenSocket) {
        params.send_status = 'error'
    }
    state.messageList.push(params)
    let sendParams = cloneDeep(params)
    sendParams.send_status = ''
    if (msg_type == 'text') {
        sendParams.msg_body.text = state.message
    }
    utils.useSocket.send(JSON.stringify(sendParams))
    state.message = ''
    inputMessage.innerHTML = ''
    initScroll()
}

//展开或关闭客户信息
const showMessageInfo = () => {
    nextTick(() => {
        chatRoomInfo.value?.open(state.toUserInfo)
    })
}
//快捷回复的点击回调
const actionsCallBack = (type, value) => {
    switch (type) {
        case 'quickReplyCallBack':
            inputMessage.innerHTML = value
            break
        case 'showEmoji':
            inputMessage.focus()
            var contextMenu = document.createElement('img')
            contextMenu.setAttribute('data-code', value.code) // 添加自定义属性
            contextMenu.className = 'emoji-img'
            contextMenu.style.margin = '0 1px'
            contextMenu.src = emojiJSON[value.code] ? emojiJSON[value.code].img_url : ''
            // 获取当前选区
            var selection = window.getSelection()
            if (selection.rangeCount > 0) {
                // 获取选区中的第一个范围
                var range = selection.getRangeAt(0)

                // 将范围的起点移到插入节点之前
                range.insertNode(contextMenu)

                // 创建一个新的范围，用于设置光标位置
                var newRange = document.createRange()

                // 将新范围的起点设置为新插入元素之后
                newRange.setStartAfter(contextMenu)
                newRange.collapse(true) // 折叠范围，这样光标就会在新插入元素后

                // 清空当前选区，并添加新的范围
                selection.removeAllRanges()
                selection.addRange(newRange)
            }
            // 等待 DOM 更新后滚动到底部
            nextTick(() => {
                inputMessage.scrollTop = inputMessage.scrollHeight
            })
            break
        case 'uploadFile':
            sendMessageFun(value.type, value)
            break
        case 'transferKf':
            //转接客服成功回调
            state.toUserInfo = null
            window.$Bus.emit('chatRoomCallBack', { type: 'transferKf' })
            break
        case 'kf_coupon':
            //发送优惠券
            sendMessageFun(value.type, value)
            break
        case 'recommend_goods':
            //发送商品
            sendMessageFun(value.type, value)
            break
        default:
            break
    }
}
const loadingRoom = (user) => {
    state.toUserInfo = user
    if (user == null) {
        return
    }
    state.chatId = user.chat_id
    state.chatRecordParams.toUser = state.toUserInfo.username
    state.userInfo = store.state.user.userInfo
    state.messageList = []
    state.chatRecordParams.page = 1
    state.easySpinning = true
    nextTick(() => {
        chatRoomInfo.value?.close()
    })
    //获取客户聊天记录
    getChatRecord()

    //每次进入聊天框上报一次消息
    reportRead()

    // 回调出去
    emits('actionsCallBack', 'messageEvent', {
        ...user,
        clearMsgNum: true,
    })
}
//获取客户聊天记录
const getChatRecord = async (chatScrollEvent = false) => {
    let scrollHeight = chatScrollRef.value?.scrollHeight || 0
    let newScrollHeight = 0
    state.spinTip = window.$t('正在获取聊天记录...')
    state.loadStatus = 'loading'
    await utils.sleep(100)
    window.$request
        .post('/im/User/getChatRecord', state.chatRecordParams)
        .then(async (res) => {
            let newData = res
                .map((v) => {
                    if (v.msg_type == 'text') {
                        v.msg_body.text = utils.initMessage(v.msg_body.text)
                    }
                    if (v.create_time) {
                        v.history_date = formattedTime(v.create_time)
                    }
                    return v
                })
                .reverse()

            state.messageList = [...newData, ...state.messageList]

            // 使用一个 Set 来追踪已经出现过的 history_date
            let seenDates = new Set()

            // 遍历数组，处理重复的 history_date
            state.messageList.forEach((message, index) => {
                if (seenDates.has(message.history_date)) {
                    // 如果这个 history_date 已经出现过，则将其赋值为空字符串
                    state.messageList[index].history_date = ''
                } else {
                    // 否则，将这个 history_date 添加到 Set 中
                    seenDates.add(message.history_date)
                }
            })

            if (res.length < state.chatRecordParams.pageSize) {
                state.loadStatus = 'nomore'
            } else {
                state.loadStatus = 'loadmore'
            }
            if (chatScrollEvent) {
                state.chatScrollMoreEvent = true
                //无缝衔接滚动条高度，实现往前面插入元素后滚动条置顶问题
                nextTick(() => {
                    newScrollHeight = chatScrollRef.value?.scrollHeight || 0
                    initScroll(0, newScrollHeight - scrollHeight)
                    // updateObserver()
                })
                return
            } else {
                state.chatScrollMoreEvent = false
            }
            state.spinTip = window.$t('正在加载...')
            await utils.sleep(300)
            state.easySpinning = false
            //获取输入的盒子
            nextTick(() => {
                inputMessage = document.querySelector('.input-message')
                initScroll(0)
                // updateObserver()
            })
        })
        .catch((err) => {})
}
// 添加监听可视区域事件
const initIntersectionObserver = () => {
    observer = new IntersectionObserver(
        (entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // 标记消息为已读
                    const messageId = entry.target.id
                    const message = state.messageList.find((v) => 'message_' + v.msg_id == messageId)
                    if (!message) return
                    const user_uid = state.userInfo ? utils.getUid(state.userInfo.username) : ''
                    const from_id = message.from_id ? utils.getUid(message.from_id) : ''
                    //判断如果是未读消息并且是别人发的消息就执行上报
                    if (
                        message &&
                        message.is_read == 0 &&
                        user_uid != from_id &&
                        message.msg_type != 'system_notify' &&
                        message.msg_type != 'kf_notify' &&
                        message.msg_type != 'customer_notify'
                    ) {
                        state.readList.push(message)
                        debounce(() => {
                            reportRead()
                        }, 500)
                    }
                }
            })
        },
        {
            root: chatScrollRef.value, // 监听的根元素为消息列表的容器
            threshold: 0.3, // 可见性阈值，超过30%可见时触发
        }
    )
}
//继续添加监听可视事件
const updateObserver = () => {
    state.messageList.forEach((message) => {
        const element = document.getElementById(`message_${message.msg_id}`)
        if (element) {
            observer.observe(element)
        }
    })
}

//上报未读消息
const reportRead = () => {
    // console.log(state.readList, '上报读了消息')
    // const newReadList = state.readList.map((v) => v.msg_id)
    // const msg_ids = newReadList.join(',')
    //直接设置为已读消息
    // state.messageList = state.messageList.map((v) => {
    //     if (v.is_read == 0 && newReadList.indexOf(v.msg_id) > -1) {
    //         v.is_read = 1 //已读
    //     }
    //     return v
    // })
    let params = {
        msg_type: 'read_report',
        from_id: state.userInfo ? state.userInfo.username : '',
        target_id: state.chatRecordParams.toUser,
        // msg_body: {
        //     msg_ids: msg_ids,
        // },
        msg_id: 'pc_' + utils.guid(11, false, 10),
        chat_id: state.chatId,
    }
    utils.useSocket.send(JSON.stringify(params))
    // state.readList = []
}

const formattedTime = (item) => {
    const now = dayjs() // 当前时间
    const time = dayjs.unix(item) // 时间戳对应的时间
    if (now.year() !== time.year()) {
        return time.format('YYYY-MM-DD') // 如果不是今年，显示年月日
    } else {
        return time.format('MM-DD') // 其他情况显示月日
    }
}

//加载更多
const chatScroll = (e) => {
    if (e.target.scrollTop == 0) {
        if (state.loadStatus != 'nomore' && state.loadStatus != 'loading') {
            state.chatRecordParams.page++
            getChatRecord(true)
        }
    }
}

//wss 监听事件
const messageEvent = (data) => {
    if (data && utils.jsonString(data)) {
        //自己的uuid
        const user_uid = state.userInfo ? utils.getUid(state.userInfo.username) : ''

        //接收数据源
        const _res = JSON.parse(data)

        let res = null

        //对方看了消息后，接收到read_report消息回调，将消息设置为已读，走到这里end
        if (_res && _res.msg_type == 'read_report') {
            state.messageList = state.messageList.map((v) => {
                if (v.is_read == 0 && utils.getUid(v.from_id) == user_uid) {
                    v.is_read = 1 //已读
                }
                return v
            })
            return
        }

        //撤回消息
        // if (_res && _res.msg_type == 'withdraw' && _res.chat_id == state.chatId) {
        //     // 移除该条消息
        //     let index = state.messageList.findIndex((v) => v.msg_id == _res.msg_id)
        //     if (index > -1) {
        //         state.messageList.splice(index, 1)
        //         window.$message.success(window.$t('撤回成功'))
        //     }
        //     return
        // }

        //消息回调有chat_id|msg_body|msg_type就表明是发来的消息
        if (_res.chat_id && _res.msg_body && _res.msg_type) {
            //深度克隆
            res = cloneDeep(_res)
            //这是别人发来的消息，进行text文本格式处理
            if (res.msg_type && res.msg_type == 'text') {
                res.msg_body.text = utils.initMessage(res.msg_body.text)
            }
        } else {
            //消息回调拿到mag_id看是不是自己发送的消息
            res = state.messageList.find((v) => v.msg_id == _res.msg_id)
        }

        //res存在执行逻辑
        if (res) {
            const target_id = res.target_id ? utils.getUid(res.target_id) : '' //目标id
            const from_id = res.from_id ? utils.getUid(res.from_id) : '' //来源id
            const chat_id = res.chat_id ? res.chat_id : '' //房间id
            const msg_type = res.msg_type ? res.msg_type : '' //消息类型

            //如果来源id是自己的就是表示发送成功的消息回调
            if (res.msg_id && from_id == user_uid) {
                let index = state.messageList.findIndex((v) => v.msg_id == res.msg_id)
                if (index > -1) {
                    state.messageList[index].send_status = _res.status == 1000 ? 'success' : 'error'
                }
            }

            //接收消息的处理逻辑
            if (
                target_id == user_uid &&
                state.toUserInfo &&
                chat_id == state.toUserInfo.chat_id &&
                msg_type != 'coupon' &&
                msg_type != 'search_orders' &&
                msg_type != 'guess_you_like'
            ) {
                state.messageList.push(res)
                initScroll()
                //是发给自己的就上报消息
                reportRead()
            }
            // 回调出去让最外面的页面进行事件散发
            emits('actionsCallBack', 'messageEvent', {
                ...res,
                isRoom: state.toUserInfo ? true : false, //是否在房间内
            })
        }
    }
}

//Socket断开与连接回调
const updateOpenSocket = (data) => {
    state.isOpenSocket = data
    //断开的情况下重置发送的消息状态为error
    if (state.messageList.length > 0 && !data) {
        state.messageList = state.messageList.map((v) => {
            if (v.send_status == 'loading') {
                v.send_status = 'error'
            }
            return v
        })
    }
}

//视频渲染完成事件，重新滚动下滚动条
const videoLoaded = () => {
    initScroll(0)
}

//重新发送
const resendMessage = (item) => {
    if (!state.isOpenSocket) {
        return
    }
    // 移除该消息的位置重新发送
    let index = state.messageList.findIndex((v) => v.msg_id == item.msg_id)
    state.messageList.splice(index, 1)
    sendMessageFun('resendMessage', item)
}

const msgItemMenuClick = (e) => {
    //撤回消息
    // if (e.key == 'withdraw') {
    //     let params = {
    //         msg_id: e.item.msg_id,
    //         from_id: e.item.from_id,
    //         target_id: e.item.target_id,
    //         msg_type: 'withdraw',
    //         chat_id: state.chatId,
    //     }
    //     utils.useSocket.send(JSON.stringify(params))
    // }
}

//回滚滚动条
const initScroll = (time = 300, scrollTop = null) => {
    nextTick(() => {
        $('.chat-message').animate({ scrollTop: scrollTop != null ? scrollTop : $('.chat-message')[0].scrollHeight }, time) // 使用 animate() 函数实现平滑滚动效果
    })
}

defineExpose({ loadingRoom, messageEvent, updateOpenSocket })
</script>
<style lang="less" scoped>
.chat-room {
    height: 100%;
    box-sizing: border-box;
    position: relative;
    :deep(.ant-drawer) {
        border: none;
        outline: none;
        .ant-drawer-wrapper-body {
            background-color: #f0f0f0;
            .ant-drawer-body {
                padding: 0;
            }
        }
    }
    .chat-room-section {
        height: calc(100% - 62px);
        position: relative;
        box-sizing: border-box;
    }
    .header {
        height: 62px;
        border-bottom: 1px solid #d0d0d0;
        box-sizing: border-box;
        padding: 0 15px;
        .name {
            font-weight: 500;
            font-size: 16px;
            color: #333333;
        }
    }
    .chat-message {
        padding: 0 20px;
        padding-bottom: 20px;
        height: calc(100% - 170px);
        box-sizing: border-box;
        overflow-x: hidden;
        .more {
            color: #333;
            text-align: center;
            user-select: none;
            height: 26px;
            font-size: 12px;
        }
    }
