import { createI18n } from "vue-i18n";
import utils from "@/common/utils/utils";
import en_US from "./lang/en_US/en_US.json";
import zh_CN from "./lang/zh_CN/zh_CN.json";
import zh_TW from "./lang/zh_TW/zh_TW.json";

const messages = {
  en_US: {
    ...en_US,
  },
  zh_CN: {
    ...zh_CN,
  },
  zh_TW: {
    ...zh_TW,
  },
};

const i18n = createI18n({
  locale: utils.getLang(), // 设置当前语言类型
  legacy: false, // 如果要支持compositionAPI，此项必须设置为false;
  globalInjection: true, // 全局注册$t方法
  missingWarn: false,
  messages,
  // missing: function (locale, key, vm) {
    // 处理缺失的翻译文本
    // messages[locale][key] = key;
    // console.log(messages);
  // },
});

export default i18n;
