<template>
    <div class="switchRoles flex flex-col align-center">
        <div class="flex flex-col align-center">
            <a-tooltip placement="top">
                <template #title>
                    <span>{{userInfo.nickname}}</span>
                </template>
                <a-skeleton-avatar :active="true" :size="'large'" :shape="'square'" v-if="!userInfo"></a-skeleton-avatar>
                <img class="avatar" v-lazy="userInfo.avatar" v-else />
            </a-tooltip>
        </div>
        <div class="action-box mt-15">
            <template v-if="!userInfo">
                <div style="overflow: hidden;border-radius: 4px;" v-for="(item) in actionList" :key="item.value" class="mb-10">
                    <a-skeleton-button :active="true" :block="true" :size="'large'" />
                </div>
            </template>
            <template v-if="userInfo">
                <div class="item" :class="{'active':actionIndex===index}" v-for="(item,index) in actionList" :key="item.value" @click="actionClick(item,index)">
                    <img class="icon" v-lazy="item.icon" />
                    <div class="title">{{item.label}}</div>
                </div>
            </template>
        </div>
        <a-modal v-model:open="modalOpen" :title="$t('切换身份')" centered :footer="null">
            <div class="kf-box mt-15 mb-15 scrollbar">
                <EasySpin :spinning="easySpinning" />
                <template v-if="kfList.length > 0">
                    <div class="kf-item" v-for="item in kfList" :key="item.username">
                        <div class="flex align-center flex-1">
                            <img class="avatar mr-20" v-lazy="item.avatar" />
                            <span class="store_name">{{item.store_name}}</span>
                        </div>
                        <div class="current-user" v-if="item.username == userInfo.username">{{$t('当前登陆')}}</div>
                        <div class="switch-roles flex align-center justify-center ml-10" v-else @click="switchRoles(item)">{{$t('切换')}}</div>
                    </div>
                </template>
                <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                    <a-empty :description="$t('暂无客服')" :image="simpleImage" />
                </div>
            </div>
        </a-modal>
    </div>
</template>

<script setup>
import { MessageFilled } from '@ant-design/icons-vue'
import { reactive, ref, onMounted, toRefs, computed } from 'vue'
import { Empty } from 'ant-design-vue'
const simpleImage = Empty.PRESENTED_IMAGE_SIMPLE
import { useStore } from 'vuex'
import { useRoute, useRouter } from 'vue-router'
import utils from '@/common/utils/utils'
const store = useStore()
const router = useRouter()
const state = reactive({
    actionList: [
        {
            value: 'message',
            label: window.$t('消息'),
            icon: require('@/assets/images/icon/message.png'),
        },
        {
            value: 'switchRoles',
            label: window.$t('切换'),
            icon: require('@/assets/images/icon/switchRoles.png'),
        },
    ],
    actionIndex: 0,
    modalOpen: false,
    kfList: [],
    easySpinning: false,
    userInfo: null,
})
const { actionList, actionIndex, modalOpen, kfList, easySpinning, userInfo } = toRefs(state)

onMounted(() => {
    setTimeout(() => {
        state.userInfo = computed(() => {
            return store.state.user.userInfo
        })
    }, 800)
})

//获取客户列表
const getMyRoles = () => {
    state.easySpinning = true
    window.$request
        .post('/im/User/myRoles')
        .then(async (res) => {
            state.easySpinning = false
            state.kfList = res
        })
        .catch((err) => {
            state.easySpinning = false
        })
}

const actionClick = (item, index) => {
    if (item.value == 'switchRoles') {
        state.modalOpen = true
        getMyRoles()
        return
    }
    state.actionIndex = index
}
//切换客户进行跳转
const switchRoles = (item) => {
    location.href = item.url
    return ;
    router.replace({
        path: '/chat',
        query: {
            username: item.username,
        },
    })
    setTimeout(() => {
        // 立即刷新页面
        location.reload(true)
    }, 300)
}
</script>
<style lang="less" scoped>
.switchRoles {
    width: 60px;
    height: 100%;
    box-sizing: border-box;
    background-color: #3975c6;
    overflow: hidden;
    padding: 16px 5px;
    border-top: 1px solid #3975c6;
    border-bottom: 1px solid #3975c6;
    .avatar {
        width: 38px;
        height: 38px;
        border-radius: 4px;
    }
    .action-box {
        width: 100%;
        overflow: hidden;
        .icon {
            width: 26px;
            height: 26px;
        }
        .item {
            text-align: center;
            color: #fff;
            font-size: 10px;
            margin-bottom: 10px;
            cursor: pointer;
            user-select: none;
            padding: 4px;
            border-radius: 4px;
        }
        .active {
            background-color: rgba(255, 255, 255, 0.1);
        }
        .item:hover {
            background-color: rgba(255, 255, 255, 0.1);
        }
    }
}
.kf-box {
    height: 400px;
    overflow-x: hidden;
    padding-top: 24px;

    .kf-item {
        display: flex;
        align-items: center;
        box-sizing: border-box;
        user-select: none;
        padding-right: 6px;
        margin-bottom: 24px;
        .avatar {
            width: 46px;
            height: 46px;
            border-radius: 50%;
        }
        .store_name {
            font-weight: 400;
            font-size: 16px;
            color: #303030;
        }
        .current-user {
            font-weight: 400;
            font-size: 16px;
            color: #3975c6;
        }
        .switch-roles {
            font-weight: 400;
            font-size: 16px;
            color: #ffffff;
            width: 50px;
            height: 30px;
            background: #3975c6;
            border-radius: 6px;
            cursor: pointer;
        }
    }
}
</style>