<template>
    <div class="user-list-box main-transition">
        <!-- <EasySpin :spinning="easySpinning" /> -->
        <div class="search">
            <a-input v-model:value="queryParams.keyword" :placeholder="$t('搜索客户名称')" @keyup="handleKeyUp">
                <template #prefix>
                    <SearchOutlined style="color:#B8B8BC" />
                </template>
            </a-input>
        </div>
        <div class="user-access-statistics flex justify-between align-center fs-12">
            <div class="flex justify-between align-center">
                <UserOutlined />
                <span style="margin-left: 4px">{{$t('最大接入')}}{{(userStatus && userStatus.max_connections) || 0}}, {{$t('已接入')}}{{(userStatus &&userStatus.current_connections) || 0}}</span>
            </div>
            <a-dropdown v-if="userStatus">
                <a class="ant-dropdown-link cursor-pointer" @click.prevent>
                    <span>{{$t('状态')}}：</span>
                    <span class="status-round mr-5" :style="{backgroundColor: userStatus.online == 1 ?'#4CAF50':'#F44336'}"></span>
                    <span class="mr-5" :style="{color: userStatus.online == 1 ?'#4CAF50':'#F44336'}">{{userStatus.online == 1?$t('在线'):$t('离线')}}</span>
                    <DownOutlined :style="{fontSize: '10px'}" />
                </a>
                <template #overlay>
                    <a-menu @click="handleMenuClick">
                        <a-menu-item key="1">
                            <a href="javascript:;">{{$t('在线')}}</a>
                        </a-menu-item>
                        <a-menu-item key="0">
                            <a href="javascript:;">{{$t('离线')}}</a>
                        </a-menu-item>
                    </a-menu>
                </template>
            </a-dropdown>
        </div>
        <div class="list scrollbar">
            <template v-if="chatLists.length>0">
                <div
                    class="item flex align-center cursor-pointer main-transition"
                    :class="index === chatListIndex?'active':''"
                    v-for="(item,index) in chatLists"
                    :key="index"
                    @click="userItemClick(item,index)"
                >
                    <a-skeleton :loading="easySpinning" active :avatar="{shape: 'circle'}" :paragraph="false">
                        <a-dropdown :trigger="['contextmenu']">
                            <a-badge :count="item.unread_msg_count || 0" class="flex flex-1 align-center" :offset="[-5, 36]">
                                <div class="left flex flex-1">
                                    <img class="avatar" v-lazy="item.avatar" alt />
                                    <div class="info flex flex-1 justify-between flex-col">
                                        <div class="title text-ellipsis">{{item.nickname}}</div>
                                        <div class="msg text-ellipsis" v-html="item.last_msg"></div>
                                    </div>
                                    <div class="flex justify-between flex-col">
                                        <div class="msg-time">{{item.last_msg_time}}</div>
                                    </div>
                                </div>
                            </a-badge>
                            <template #overlay>
                                <a-menu @click="huserItemMenuClick($event,item)">
                                    <a-menu-item key="delete">{{$t('删除')}}</a-menu-item>
                                </a-menu>
                            </template>
                        </a-dropdown>
                    </a-skeleton>
                </div>
            </template>
            <template v-else>
                <div class="flex align-center justify-center" style="width: 100%;height:100%;margin-top: -54px">
                    <a-empty :description="$t('暂无会话')" :image="simpleImage" />
                </div>
            </template>
        </div>
    </div>
</template>

<script setup>
import { defineComponent, reactive, ref, getCurrentInstance, computed, onMounted, toRefs, createVNode } from 'vue'
import { SearchOutlined, UserOutlined, DownOutlined, ExclamationCircleOutlined } from '@ant-design/icons-vue'
import { Empty } from 'ant-design-vue'
const simpleImage = Empty.PRESENTED_IMAGE_SIMPLE
import { useStore } from 'vuex'
import utils from '@/common/utils/utils'
import { cloneDeep } from 'lodash'
import dayjs from 'dayjs'
const store = useStore()
const emits = defineEmits(['userItemClick'])
const state = reactive({
    easySpinning: true,
    userStatus: null,
    chatLists: [{}, {}, {}, {}, {}, {}],
    chatListItem: null,
    chatListIndex: -1,
    queryParams: {
        keyword: '', //关键词检索
        page: 1, //页码
        limit: 200, //条数
    },
})
const { easySpinning, userStatus, chatLists, queryParams, chatListIndex } = toRefs(state)

const userItemClick = (item, index) => {
    if (!store.state.user.userInfo || state.easySpinning) {
        return
    }
    if (state.chatListIndex == index) return
    state.chatListIndex = index
    state.chatListItem = item
    initListSort()
    emits('userItemClick', item)
}
//下拉菜单点击
const handleMenuClick = (e) => {
    window.$request.post('/im/User/setStatus', { status: e.key }).then((res) => {
        window.$message.success(window.$t('操作成功'))
        getUserStat()
    })
}
//客服状态
const getUserStat = () => {
    window.$request.post('/im/User/stat').then((res) => {
        state.userStatus = res
    })
}
//会话列表
const getChatLists = () => {
    state.easySpinning = true
    window.$request
        .post('/im/User/chatLists', state.queryParams)
        .then((res) => {
            state.chatLists = res.map((v) => {
                v.last_msg = utils.initMessage(v.last_msg)
                return v
            })
            state.easySpinning = false
            initListSort('search')
        })
        .catch((err) => {
            state.easySpinning = false
        })
}

const search = () => {
    if (!store.state.user.userInfo) {
        return
    }
    // 处理回车键事件的逻辑
    state.queryParams.page = 1
    state.chatLists = [{}, {}, {}, {}, {}, {}]
    getChatLists()
}

//搜索
const handleKeyUp = (event) => {
    if (event.key === 'Enter') {
        search()
    }
}
//会话列表右键事件
const huserItemMenuClick = (e, item) => {
    switch (e.key) {
        case 'delete':
            window.$Modal.confirm({
                title: window.$t('确定删除该会话吗？'),
                icon: createVNode(ExclamationCircleOutlined),
                okType: 'danger',
                onOk() {
                    window.$request.post('/im/User/delChat', { id: item.id }).then((res) => {
                        window.$message.success(window.$t('删除成功'))
                        if (state.chatListItem.chat_id == item.chat_id) {
                            state.chatListIndex = -1
                            state.chatListItem = null
                            emits('userItemClick', null)
                        }
                        search()
                    })
                },
                onCancel() {},
            })
            break

        default:
            break
    }
}
//ws 传过来的message事件
const updateMessage = (e) => {
    let index = state.chatLists.findIndex((v) => v.chat_id == e.chat_id)
    let user_uid = utils.getUid(store.state.user.userInfo.username)

    //清除角标
    if (e.clearMsgNum) {
        state.chatLists[index].unread_msg_count = 0
        return
    }

    let target_id = utils.getUid(e.target_id)
    let from_id = utils.getUid(e.from_id)

    if (user_uid == target_id || user_uid == from_id) {
        if (index > -1) {
            //判断不在房间内就或者不在当前聊天框内才加消息数
            if (user_uid == target_id && (!e.isRoom || state.chatLists[state.chatListIndex].chat_id != e.chat_id)) {
                state.chatLists[index].unread_msg_count++
            }
            if (e.msg_body) {
                let last_msg = ''
                switch (e.msg_type) {
                    case 'text':
                        last_msg = e.msg_body.text
                        break
                    case 'image':
                        last_msg = window.$t('[图片]')
                        break
                    case 'video':
                        last_msg = window.$t('[视频]')
                        break
                    default:
                        last_msg = window.$t('[特殊消息]')
                        break
                }
                state.chatLists[index].last_msg = last_msg
                //每发送来一个消息没有时间自己加一个当前时间
                // 获取当前时间的月-日 时-分
                const last_msg_time = dayjs().format('MM-DD HH:mm')
                // 将时间字符串转换为秒级时间戳
                const timestampInSeconds = dayjs().unix()
                state.chatLists[index].last_msg_time = last_msg_time
                state.chatLists[index].last_time = timestampInSeconds
            }
        } else {
            search()
        }
    }
    initListSort()
}
const loadingPage = () => {
    getUserStat()
    getChatLists()
}

const setChatListIndex = (value = -1) => {
    state.chatListIndex = value
}

const initListSort = (type) => {
    state.chatLists.sort((a, b) => b.last_time - a.last_time)
    if (state.chatListItem) {
        state.chatListIndex = state.chatLists.findIndex((v) => v.chat_id == state.chatListItem.chat_id)
    }
}

defineExpose({ loadingPage, updateMessage, setChatListIndex, initListSort })
</script>
<style lang="less" scoped>
.user-list-box {
    width: 272px;
    height: 100%;
    position: relative;
    display: flex;
    flex-direction: column;
    .search {
        padding: 15px;
        background-color: #fff;
    }
    .user-access-statistics {
        height: 44px;
        line-height: 44px;
        padding: 0 15px;
        text-align: left;
        background-color: #f0f0f0;

        color: #3d3d3d;
        .status-round {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            display: inline-block;
        }
    }
    .list {
        flex: 1;
        overflow: hidden;
        overflow-y: overlay !important;
        background-color: #fff;
        &::-webkit-scrollbar {
            width: 4px !important;
        }
        .item {
            padding: 12px;
            user-select: none;
            .left {
                overflow: hidden;
                .avatar {
                    width: 40px;
                    height: 40px;
                    border-radius: 50%;
                }
                .info {
                    width: 150px;
                    margin-left: 8px;
                    overflow: hidden;
                    .title {
                        font-weight: 350;
                        font-size: 14px;
                        color: #333333;
                    }
                    .msg {
                        font-weight: 400;
                        font-size: 12px;
                        color: #999999;
                    }
                }
            }
            .msg-time {
                font-weight: 350;
                font-size: 10px;
                color: #999999;
            }
            .user-status {
                width: 40px;
                height: 17px;
                border-radius: 3px;
                border: 1px solid var(--primary-color);
                font-weight: 350;
                font-size: 12px;
                color: var(--primary-color);
                display: flex;
                align-items: center;
                justify-content: center;
            }
        }
        .item:hover {
            background-color: rgba(0, 0, 0, 0.05);
        }
        .active {
            background-color: rgba(0, 0, 0, 0.1) !important;
        }
    }
}
</style>