import * as storage from "./storage";
import store from "@/store";
import defaultSetting from "./defaultSetting";
import emojiJSON from '@/common/utils/emoji.json'
let BASE_URL = defaultSetting.requestDomain;
if (process.env.NODE_ENV === "development") {
  BASE_URL = BASE_URL + "/api";
}
const dir =
  process.env.NODE_ENV === "production" ? "/packapp/customer_service_pc/" : "";
const utils = {
  useSocket: null,
  BASE_URL,
  dir,
  ...storage,
  isLogin: () => {
    return store.getters.isLogin;
  },
  checkLogin: () => {
    return new Promise((resolve) => {
      if (store.getters.isLogin) {
        resolve(true);
      } else {
        resolve();
      }
    });
  },
  //延时调用
  sleep: (value) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve();
      }, value);
    });
  },

  /**
   * @description: 获取路由参数
   */
  getUrlQuery: (variable, url) => {
    const query = url.split("?")[1];
    const queryObj = {};
    if (query) {
      const vars = query.split("&");
      for (var i = 0; i < vars.length; i++) {
        var pair = vars[i].split("=");
        queryObj[pair[0]] = pair[1];
        if (pair[0] == variable) {
          return pair[1];
        }
      }
    }
    return queryObj;
  },
  colorRgb: (colorHex, opacityVal = 1) => {
    // 16进制颜色值的正则
    let reg = /^#([0-9a-fA-f]{3}|[0-9a-fA-f]{6})$/;
    // 把颜色值变成小写
    let color = colorHex.toLowerCase();
    if (reg.test(color)) {
      // 如果只有三位的值，需变成六位，如：#fff => #ffffff
      if (color.length === 4) {
        let colorNew = "#";
        for (let i = 1; i < 4; i += 1) {
          colorNew += color.slice(i, i + 1).concat(color.slice(i, i + 1));
        }
        color = colorNew;
      }
      // 处理六位的颜色值，转为RGB
      let colorChange = [];
      for (let i = 1; i < 7; i += 2) {
        colorChange.push(parseInt("0x" + color.slice(i, i + 2)));
      }
      return "rgba(" + colorChange.join(",") + "," + opacityVal + ")";
    } else {
      return color;
    }
  },
  isJSONStr: (str) => {
    if (/^\d+$/.test((str + "").trim())) {
      return false;
    }

    try {
      JSON.parse(str);
      return true;
    } catch (e) {
      return false;
    }
  },
  isObject: (val) => {
    return val !== null && utils.is(val, "Object");
  },
  /**
   * 本算法来源于简书开源代码，详见：https://www.jianshu.com/p/fdbf293d0a85
   * 全局唯一标识符（uuid，Globally Unique Identifier）,也称作 uuid(Universally Unique IDentifier)
   * 一般用于多个组件之间,给它一个唯一的标识符,或者v-for循环的时候,如果使用数组的index可能会导致更新列表出现问题
   * 最可能的情况是左滑删除item或者对某条信息流"不喜欢"并去掉它的时候,会导致组件内的数据可能出现错乱
   * v-for的时候,推荐使用后端返回的id而不是循环的index
   * @param {Number} len uuid的长度
   * @param {Boolean} firstU 将返回的首字母置为"u"
   * @param {Nubmer} radix 生成uuid的基数(意味着返回的字符串都是这个基数),2-二进制,8-八进制,10-十进制,16-十六进制
   */
  guid: (len = 32, firstU = true, radix = null) => {
    let chars =
      "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".split(
        ""
      );
    let uuid = [];
    radix = radix || chars.length;

    if (len) {
      // 如果指定uuid长度,只是取随机的字符,0|x为位运算,能去掉x的小数位,返回整数位
      for (let i = 0; i < len; i++)
        uuid[i] = chars[0 | (Math.random() * radix)];
    } else {
      let r;
      // rfc4122标准要求返回的uuid中,某些位为固定的字符
      uuid[8] = uuid[13] = uuid[18] = uuid[23] = "-";
      uuid[14] = "4";

      for (let i = 0; i < 36; i++) {
        if (!uuid[i]) {
          r = 0 | (Math.random() * 16);
          uuid[i] = chars[i == 19 ? (r & 0x3) | 0x8 : r];
        }
      }
    }
    // 移除第一个字符,并用u替代,因为第一个字符为数值时,该guuid不能用作id或者class
    if (firstU) {
      uuid.shift();
      return "u" + uuid.join("");
    } else {
      return uuid.join("");
    }
  },
  setUseSocket: (data) => {
    utils.useSocket = data;
  },
  jsonString: (value) => {
    if (typeof value == "string") {
      try {
        var obj = JSON.parse(value);
        if (typeof obj == "object" && obj) {
          return true;
        } else {
          return false;
        }
      } catch (e) {
        return false;
      }
    }
    return false;
  },
  initMessage: (text) => {
    if (!text) return;
    // 定义一个函数来将特定格式的字符串替换为图片
    function replaceWithEmojiImages(text) {
      // 定义一个正则表达式来匹配 /::1f600::/ 格式的字符串
      const regex = /\/::(.*?)::\//g;

      // 使用 replace 方法和回调函数进行替换
      return text.replace(regex, (match, p1) => {
        // 构建图片标签
        const imgSrc = `${emojiJSON[match] ? emojiJSON[match].img_url : ""}`; // 假设图片存储在这个路径
        return `<img data-code="${match}" src="${imgSrc}" class="emoji-img"/>`;
      });
    }

    // 调用函数进行替换
    const outputText = replaceWithEmojiImages(text);
    return outputText;
  },
  getUid:(str)=>{
    let result = str.split('_').slice(0, 2).join('_');
    return result
  }
};
export default utils;
