// 引入Vue Router
import { createRouter, createWebHistory } from "vue-router";
import { getToken } from "@/common/utils/storage";
import store from "@/store/index";
import i18n from "@/locale/index";
import utils from "@/common/utils/utils";
import Chat from "@/views/Chat/Chat";
import ErrorPage from "@/views/ErrorPage/index";
const $t = i18n.global.t;
let wapTitle = "";
// await store.dispatch("GetAiConfig")
const config = "";
wapTitle = config ? config.software_name : $t("客服");
//获取配置
const routes = [
  // plan on directly navigating to the not-found route using its name
  // { path: "/:pathMatch(.*)*", name: "not-found", component: NotFound },
  // if you omit the last `*`, the `/` character in params will be encoded when resolving or pushing
  // { path: "/:pathMatch(.*)", name: "bad-not-found", component: NotFound },
  {
    path: "/",
    redirect: "/chat",
  },
  {
    path: "/chat",
    name: "Chat",
    component: Chat,
    meta: {
      // requireAuth: true,
      title: $t("聊天"),
    },
  },
  {
    path: "/errorPage",
    name: "ErrorPage",
    component: ErrorPage,
    meta: {
      title: $t("访问失败"),
    },
  },
];
// 创建路由实例
const router = createRouter({
  routes,
  history: createWebHistory(utils.dir),
});
// 路由守卫
router.beforeEach((to, from, next) => {
  // console.log(to, from);
  document.title = wapTitle + (to.meta.title ? "-" + to.meta.title : "");
  // let token = getToken();
  let token = "";
  if (to.meta.requireAuth == true) {
    // 需要登录权限进入的路由
    if (!token) {
      // 获取不到登录信息
      // next({
      //   path: "/login",
      //   query: {
      //     redirectPath: to.path,
      //   },
      // });
      location.href = `${utils.dir}/login?redirectPath=${to.path}`;
    } else {
      // 获取到登录信息，进行下一步
      return next();
    }
  } else {
    // 不需要登录权限的路由直接进行下一步
    return next();
  }
});
export default router;
