export const NAME = "CUSTOMER_SERVICE_PC_";
export const getOrgId = () => {
  let data = localStorage.getItem(NAME + "ORG_ID");
  return data ? data : 1;
};

export const setOrgId = (orgId) => {
  return new Promise((resolve) => {
    localStorage.setItem(NAME + "ORG_ID", orgId);
    resolve();
  });
};

export const setToken = (token) => {
  return new Promise((resolve) => {
    localStorage.setItem(NAME + "USER_TOKEN_" + getOrgId(), token);
    resolve();
  });
};

export const getToken = () => {
  return localStorage.getItem(NAME + "USER_TOKEN_" + getOrgId());
};

export const clearToken = () => {
  return localStorage.removeItem(NAME + "USER_TOKEN_" + getOrgId());
};

export const setUserInfo = (userInfo) => {
  return new Promise((resolve) => {
    localStorage.setItem(
      NAME + "USER_INFO_" + getOrgId(),
      JSON.stringify(userInfo)
    );
    resolve();
  });
};
export const getUserInfo = () => {
  let userInfo = localStorage.getItem(NAME + "USER_INFO_" + getOrgId());
  return userInfo ? JSON.parse(userInfo) : null;
};
export const clearUserInfo = () => {
  return localStorage.removeItem(NAME + "USER_INFO_" + getOrgId());
};

export const setLang = (value) => {
  return localStorage.setItem(NAME + "LANG_" + getOrgId(), value);
};
export const getLang = () => {
  let lang = localStorage.getItem(NAME + "LANG_" + getOrgId());
  return lang ? lang : "zh_CN";
};
export const setWarnPopup = (value) => {
  return localStorage.setItem(NAME + "WARN_POPUP_" + getOrgId(), value);
};
export const getWarnPopup = (value) => {
  return localStorage.getItem(NAME + "WARN_POPUP_" + getOrgId(), value);
};

export const setCurrencySymbol = (value) => {
  return localStorage.setItem(NAME + "CURRENCY_SYMBOL" + getOrgId(), value);
};

export const getCurrencySymbol = () => {
  return localStorage.getItem(NAME + "CURRENCY_SYMBOL" + getOrgId());
};
