import utils from "@/common/utils/utils";
import request from "@/common/utils/request";
import * as storage from "@/common/utils/storage";

const user = {
  state: {
    orgId: "", // org_id
    userInfo: "",
    token: "",
    config: null,
  },
  mutations: {
    SET_ORG_ID: (state, orgId) => {
      state.orgId = orgId;
      storage.setOrgId(orgId);
    },
    SET_TOKEN: (state, token) => {
      state.token = token;
    },
    SET_USER_INFO: (state, user) => {
      state.userInfo = user;
    },
    LOGOUT: (state, org_id) => {
      state.userInfo = null;
      state.token = null;
      storage.clearUserInfo();
      storage.clearToken();
      if (!org_id) {
        localStorage.clear();
      }
    },
    SET_AI_CONFIG: (state, info) => {
      state.config = info;
    },
    // 动态改变主题色
    SET_MAIN_COLOR: (state, color) => {
      document.documentElement.style.setProperty("--primary-color", color);
      //0.1到0.9透明度
      for (let i = 1; i < 10; i++) {
        document.documentElement.style.setProperty(
          `--primary-color-rgba-${i}`,
          utils.colorRgb(color, i / 10)
        );
      }
    },
  },
  actions: {
    /**
     * @description: 设置org_id
     */
    SetOrgId({ commit }, orgId) {
      return new Promise((resolve) => {
        commit("SET_ORG_ID", orgId);
        resolve();
      });
    },
    /**
     * @description: 登出
     */
    Logout({ commit }) {
      // 保留org_id
      let org_id = utils.getOrgId();
      return new Promise((resolve) => {
        commit("SET_ORG_ID", org_id);
        commit("LOGOUT", org_id);
        resolve();
      });
    },
    SetToken({ commit }, token) {
      return new Promise((resolve) => {
        commit("SET_TOKEN", token);
        resolve();
      });
    },
    //登录
    login({ state, commit }, params) {
      return new Promise((resolve) => {
        if (params.username == state.userInfo.username) {
          resolve(state.userInfo);
          return;
        }
        window.$Bus.emit("updateSpin", {
          flag: true,
          tip: window.$t("登陆中..."),
        });
        request
          .post("/im/User/login", params)
          .then((res) => {
            window.$Bus.emit("updateSpin", { flag: false, tip: "" });
            commit("SET_TOKEN", res.token);
            commit("SET_USER_INFO", res);
            resolve(res);
          })
          .catch((err) => {
            resolve();
          });
      });
    },
    //获取用户信息
    getApiUserInfo({ state, commit }, username) {
      return new Promise((resolve, reject) => {
        request
          .post("/im/User/getUserInfo", {
            username: username,
          })
          .then((res) => {
            resolve(res);
          })
          .catch((err) => {
            reject();
          });
      });
    },
    //获取配置项
    GetConfig({ state, commit }) {
      return new Promise((resolve) => {
        if (state.config) {
          commit("SET_MAIN_COLOR", state.config.main_color);
          resolve(state.config);
        } else {
          // request.get("/work_friend", "/api/config").then((res) => {
          // if (res.list) {
          let res = { list: {} };
          let { main_color = null, currency_symbol = "" } = res.list;
          res.list.main_color = main_color ? main_color : "#4EAC60";
          commit("SET_MAIN_COLOR", res.list.main_color);
          commit("SET_AI_CONFIG", res.list);
          currency_symbol && storage.setCurrencySymbol(currency_symbol);
          resolve(res.list);
          // } else {
          //   resolve();
          // }
          // })
        }
      });
    },
  },
};

export default user;
