// JavaScript version of Socket class and useSocket function
import { ref, onUnmounted } from "vue";
class Socket {
  constructor(url, opts = {}) {
    this.ws = null;
    this.reconnectAttempts = 0;
    this.listeners = {};
    this.heartbeatInterval = null;
    this.url = url;
    this.opts = {
      heartbeatInterval: 30000, //心跳间隔，即发送心跳包的时间间隔。在 WebSocket 连接期间，客户端会定期发送心跳包以保持连接活跃。这里设置为 30000 毫秒（30 秒），意味着每隔 30 秒发送一次心跳包。
      reconnectInterval: 5000, //重连间隔，指的是在连接断开后，重新尝试连接的时间间隔。如果 WebSocket 连接断开，客户端会在指定的时间间隔后尝试重新连接。这里设置为 5000 毫秒（5 秒），意味着每隔 5 秒尝试一次重新连接。
      maxReconnectAttempts: 5, //最大重连尝试次数，限制了断线后尝试重新连接的最大次数。如果达到指定的尝试次数仍然无法连接成功，将停止尝试。这里设置为 5 次，意味着如果连接断开，最多尝试重新连接 5 次。
      heartbeatParams: "ping",
      ...opts,
    };

    this.init();
  }

  init() {
    this.ws = new WebSocket(this.url);

    this.ws.onopen = this.onOpen.bind(this);
    this.ws.onmessage = this.onMessage.bind(this);
    this.ws.onerror = this.onError.bind(this);
    this.ws.onclose = this.onClose.bind(this);
  }

  onOpen(event) {
    // console.log("WebSocket opened:", event);
    this.reconnectAttempts = 0;
    this.startHeartbeat();
    this.emit("open", event);
  }

  onMessage(event) {
    // console.log("WebSocket message received:", event.data);
    this.emit("message", event.data);
  }

  onError(event) {
    // console.error("WebSocket error:", event);
    this.emit("error", event);
  }

  onClose(event) {
    // console.log("WebSocket closed:", event);
    this.stopHeartbeat();
    this.emit("close", event);

    if (this.reconnectAttempts < this.opts.maxReconnectAttempts) {
      setTimeout(() => {
        this.reconnectAttempts++;
        this.emit("reconnect", event);
        this.init();
      }, this.opts.reconnectInterval);
    } else {
      this.emit("reconnectEnd", event);
    }
  }

  startHeartbeat() {
    if (!this.opts.heartbeatInterval) return;

    this.heartbeatInterval = window.setInterval(() => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        this.ws.send(this.opts.heartbeatParams);
      }
    }, this.opts.heartbeatInterval);
  }

  stopHeartbeat() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  send(data) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(data);
    } else {
      // console.error("WebSocket is not open. Cannot send:", data);
    }
  }

  on(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  off(event) {
    if (this.listeners[event]) {
      delete this.listeners[event];
    }
  }

  emit(event, data) {
    this.listeners[event]?.forEach((callback) => callback(data));
  }
}

export function useSocket(url, opts) {
  const socket = new Socket(url, opts);
  onUnmounted(() => {
    socket.off("open");
    socket.off("message");
    socket.off("error");
    socket.off("close");
    socket.off("reconnect");
    socket.off("reconnectEnd");
  });

  return {
    socket,
    send: socket.send.bind(socket),
    on: socket.on.bind(socket),
    off: socket.off.bind(socket),
  };
}