import axios from "axios";
import { notification, message } from "ant-design-vue";
import store from "../../store";
import defaultSetting from "./defaultSetting";
import utils from "./utils";
function getVuexData() {
  let vuexData = window.sessionStorage.getItem(
    `${defaultSetting.from}_${defaultSetting.name}_vuex`
  );
  let userInfo = "";
  if (vuexData) {
    vuexData = JSON.parse(vuexData);
    userInfo = vuexData.user.userInfo;
  }
  return { userInfo, vuexData };
}

let BASE_URL = defaultSetting.requestDomain + "/v20/public/index.php";
if (process.env.NODE_ENV === "development") {
  BASE_URL = defaultSetting.requestDomain + "/api/v20/public/index.php";
}
// 创建axios实例
const service = axios.create({
  // API 请求的默认前缀
  baseURL: BASE_URL,
  // 请求超时时间
  timeout: 600000,
});

/**
 * @description: 请求异常处理
 * @param*data返回数据
 * @return*
 * @status    返回的状态码对应的类型:
 *          *1000 正常响应
 *          *1001 业务逻辑错误
 *          *1002 登录超时
 *          *1005 前端错误(缺少参数等)
 */

export const errorHandler = (response) => {
  // 代码错误提示
  const errorNotification = (tip, status) => {
    notification["error"]({
      message: window.$t("错误"),
      description: tip,
    });
  };
  if (response.data) {
    const { config } = response;
    const { status, msg } = response.data;
    const token = getVuexData().userInfo ? getVuexData().userInfo.token : "";
    if (config && config.data && status == 1000) {
      return Promise.resolve(response.data);
    } else {
      switch (status) {
        case 1001:
          errorNotification(msg || "接口响应错误,请检查逻辑代码等!", status);
          break;
        case 1005:
          errorNotification(msg || "前端请求错误,请检查请求参数等!", status);
          break;
        case 1002:
          if (token) {
            message.warning("登录超时,请重新登录~");
          }
          break;
        case 1003:
          errorNotification(msg || "权限错误!", status);
          break;
        case 3602:
          if (utils.isLogin()) {
            errorNotification("登录状态已过期，请重新登录", status);
          } else {
            errorNotification("请登录", status);
          }
          // 清除token,进入登录页面
          store.dispatch("Logout").then(() => {
            location.replace(utils.dir + "/login");
          });
          break;
        default:
      }
      return Promise.reject(response.data);
    }
  } else {
    errorNotification("网络请求超时，请稍后再试!", "error");
    return Promise.reject(response);
  }
};

// request拦截器
service.interceptors.request.use((config) => {
  // const user_token = utils.getToken();
  // if (user_token) {
  //   config.headers["user-token"] = user_token;
  // }
  if (config.params) {
    config.params.cur_env = "pc";
  }
  if (config.data) {
    config.data.cur_env = "pc";
    if (!config.data.username && getVuexData().userInfo) {
      config.data["username"] = getVuexData().userInfo.username;
    }
  }

  return config;
}, errorHandler);

// response拦截器
service.interceptors.response.use((response) => {
  if (response.data) {
    const { status, msg } = response.data;
    if (status === 1000) {
      if (response.config && response.config.data) {
        let params = JSON.parse(response.config.data);
        if (params.isTip) {
          message.success(msg);
        }
      }
      return response.data;
    }
  }
  return errorHandler(response);
}, errorHandler);

const request = {
  BASE_URL,
  // get请求 url 请求地址
  get(url, params = {}) {
    return new Promise((resolve, reject) => {
      service
        .get(url, {
          params,
        })
        .then((res) => {
          if (params.needMsg) {
            resolve(res);
          }
          resolve(res.data);
        })
        .catch((err) => {
          reject(err);
        });
    });
  },
  //   post请求
  post(url, params = {}) {
    return new Promise((resolve, reject) => {
      service
        .post(url, params)
        .then((res) => {
          if (params.needMsg) {
            resolve(res);
          }
          resolve(res.data);
        })
        .catch((err) => {
          reject(err);
        });
    });
  },
  //  put请求
  put(url, params = {}) {
    return new Promise((resolve, reject) => {
      service
        .put(url, params)
        .then((res) => {
          if (params.needMsg) {
            resolve(res);
          }
          resolve(res.data);
        })
        .catch((err) => {
          reject(err);
        });
    });
  },
  // delete请求
  del(url, params = {}) {
    return new Promise((resolve, reject) => {
      service
        .delete(url, { data: params })
        .then((res) => {
          if (params.needMsg) {
            resolve(res);
          }
          resolve(res.data);
        })
        .catch((err) => {
          reject(err);
        });
    });
  },
  // patch请求
  patch(url, params = {}) {
    return new Promise((resolve, reject) => {
      service
        .patch(url, params)
        .then((res) => {
          if (params.needMsg) {
            resolve(res);
          }
          resolve(res.data);
        })
        .catch((err) => {
          reject(err);
        });
    });
  },
  upload(url, params = {}) {
    return new Promise((resolve, reject) => {
      const data = new FormData();

      for (var key in params) {
        data.append(key, params[key]);
      }

      service
        .post(url, data)
        .then((res) => {
          if (params.needMsg) {
            resolve(res);
          }
          resolve(res.data);
        })
        .catch((err) => {
          reject(err);
        });
    });
  },
};

export default request;
