<template>
    <div class="actions flex justify-between">
        <div class="left">
            <a-popover placement="topLeft" v-model:open="emojiOpen" trigger="click">
                <template #content>
                    <div class="emoji-box scrollbar">
                        <div class="item main-transition" v-for="(item,key) of emojiJSON" :key="key" @click="showEmoji(item)" :title="item.name">
                            <img v-lazy="item.img_url" class="emoji-img" />
                        </div>
                    </div>
                </template>
                <img class="icon" src="@/assets/images/icon/biaoqing.png" :title="$t('表情')" />
            </a-popover>
        </div>
        <div class="right">
            <template v-for="item in state.operateList">
                <template v-if="item.action == 'photo'">
                    <a-upload
                        accept="image/*"
                        :showUploadList="false"
                        :name="uploadName"
                        :data="uploadData"
                        :action="uploadAction"
                        :before-upload="beforeUpload"
                        @change="handleChange"
                        :key="item.action"
                    >
                        <img class="icon" :src="item.icon" :title="item.title" />
                    </a-upload>
                </template>
                <template v-else-if="item.action == 'video'">
                    <a-upload
                        accept="video/*"
                        :showUploadList="false"
                        :name="uploadName"
                        :data="uploadData"
                        :action="uploadAction"
                        :before-upload="beforeUpload"
                        @change="handleChange"
                        :key="item.action"
                    >
                        <img class="icon" :src="item.icon" :title="item.title" />
                    </a-upload>
                </template>
                <template v-else-if="item.action == 'transfer'">
                    <a-popover placement="topRight" v-model:open="transferKFVisible" trigger="click" :key="item.action">
                        <template #content>
                            <div class="kf-box">
                                <EasySpin :spinning="easySpinning" :tip="tip" />
                                <div class="header flex align-center justify-between">
                                    <span class="title">{{ $t('选择转交给的客服') }}</span>
                                    <a-button type="primary" size="small" @click="kfConfirm">{{$t('确定')}}</a-button>
                                </div>
                                <div class="kfList flex scrollbar">
                                    <a-radio-group v-model:value="kfValue" name="radioGroup" v-if="kfList.length > 0">
                                        <div class="item" v-for="(item, index) in kfList" :key="item.first_letter">
                                            <div class="first-letter flex align-center">{{ item.first_letter }}</div>
                                            <div class="kf-item flex align-center" v-for="items in item.kf_lists" :key="items.username">
                                                <a-radio :value="items.username">
                                                    <div class="flex align-center">
                                                        <img class="avatar ml-10 mr-10" v-lazy="items.avatar" />
                                                        <span>{{ items.name }}</span>
                                                    </div>
                                                </a-radio>
                                            </div>
                                        </div>
                                    </a-radio-group>
                                    <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                                        <a-empty :description="$t('暂无客服')" :image="simpleImage" />
                                    </div>
                                </div>
                            </div>
                        </template>
                        <img class="icon" :src="item.icon" :title="item.title" @click="actionsClick('kefu')" />
                    </a-popover>
                </template>
                <template v-else-if="item.action == 'quick_reply'">
                    <a-popover placement="topRight" v-model:open="quickReplyVisible" trigger="click" :key="item.action">
                        <template #content>
                            <div class="kf-box" style="width: 420px">
                                <EasySpin :spinning="easySpinning" :tip="tip" />
                                <div class="header flex align-center justify-between">
                                    <span class="title">{{ $t('快捷回复管理') }}</span>
                                    <div class="cursor-pointer">
                                        <a-dropdown :placement="'bottom'">
                                            <a class="ant-dropdown-link" @click.prevent>
                                                <PlusOutlined :style="{ fontSize: '18px', color: '#888888' }" />
                                            </a>
                                            <template #overlay>
                                                <a-menu>
                                                    <a-menu-item>
                                                        <a href="javascript:;" @click="addQuickReply('phrase')">{{ $t('添加个人短语') }}</a>
                                                    </a-menu-item>
                                                    <a-menu-item>
                                                        <a href="javascript:;" @click="addQuickReply('phraseGrouping')">{{ $t('添加个人短语分组') }}</a>
                                                    </a-menu-item>
                                                </a-menu>
                                            </template>
                                        </a-dropdown>
                                    </div>
                                </div>
                                <div class="quickReply-nav flex justify-center">
                                    <div
                                        class="item flex align-center main-transition"
                                        :class="quickReplyNavIndex === index ? 'active' : ''"
                                        v-for="(item, index) in quickReplyNavList"
                                        :key="item.value"
                                        @click="navClick(item, index)"
                                    >{{ item.name }}</div>
                                </div>
                                <div class="quickReply-list flex" v-if="quickReplyNavList[quickReplyNavIndex].list.length > 0">
                                    <div class="left-bar scrollbar">
                                        <div v-for="(item, index) in quickReplyNavList[quickReplyNavIndex].list" :key="index">
                                            <a-dropdown :trigger="quickReplyNavIndex == 1?['contextmenu']:''">
                                                <div
                                                    class="item main-transition"
                                                    :class="quickReplyleftBarIndex === index ? 'left-bar-active' : ''"
                                                    @click="navLeftBarClick(item, index)"
                                                    :title="quickReplyNavIndex == 1?$t('按鼠标右键编辑或删除分组'):''"
                                                >{{ item.text }}</div>
                                                <template #overlay v-if="quickReplyNavIndex == 1">
                                                    <a-menu @click="itemMenuClick($event,'phraseGrouping',item)">
                                                        <a-menu-item key="edit">{{$t('编辑分组')}}</a-menu-item>
                                                        <a-menu-item key="delete">{{$t('删除分组')}}</a-menu-item>
                                                    </a-menu>
                                                </template>
                                            </a-dropdown>
                                        </div>
                                    </div>
                                    <div class="right-bar flex-1 scrollbar">
                                        <template v-if="quickReplyNavList[quickReplyNavIndex].list[quickReplyleftBarIndex].children.length > 0">
                                            <div v-for="item in quickReplyNavList[quickReplyNavIndex].list[quickReplyleftBarIndex].children" :key="item.id">
                                                <a-dropdown :trigger="quickReplyNavIndex == 1?['contextmenu']:''">
                                                    <div class="item main-transition" @click="navRightBarClick(item)" :title="quickReplyNavIndex == 1?$t('按鼠标右键编辑或删除快捷语'):''">{{ item.text }}</div>
                                                    <template #overlay v-if="quickReplyNavIndex == 1">
                                                        <a-menu @click="itemMenuClick($event,'phrase',item)">
                                                            <a-menu-item key="edit">{{$t('编辑快捷语')}}</a-menu-item>
                                                            <a-menu-item key="delete">{{$t('删除快捷语')}}</a-menu-item>
                                                        </a-menu>
                                                    </template>
                                                </a-dropdown>
                                            </div>
                                        </template>
                                        <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                                            <a-empty :description="$t('暂无数据')" :image="simpleImage" />
                                        </div>
                                    </div>
                                </div>
                                <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                                    <a-empty :description="$t('暂无数据')" :image="simpleImage" />
                                </div>
                            </div>
                        </template>
                        <img class="icon" :src="item.icon" :title="item.title" @click="actionsClick('quick_reply',true)" />
                    </a-popover>
                </template>
                <template v-else-if="item.action == 'coupon'">
                    <img class="icon" :src="item.icon" :title="item.title" @click="actionsClick('kf_coupon')" :key="item.action" />
                </template>
                <template v-else-if="item.action == 'recommend_goods'">
                    <img class="icon" :src="item.icon" :title="item.title" @click="actionsClick('recommend_goods')" :key="item.action" />
                </template>
            </template>
        </div>
        <a-modal
            wrapClassName="messageFooterActionsModalClass"
            v-model:open="modalOpen"
            :title="modelTitle"
            @ok="handleOk"
            @cancel="cancel"
            centered
            :destroyOnClose="true"
            :confirmLoading="confirmLoading"
        >
            <!-- 短语 -->
            <div v-if="modalType == 'quickReply'" class="mt-15 mb-15">
                <a-form :model="formState" ref="form" :label-col="{ span: 5 }" :wrapper-col="{ span: 18 }" autocomplete="off">
                    <a-form-item :label="$t('排序值')" name="sort" :rules="[{ required: true, message: $t('请填写排序值') }]">
                        <a-input-number v-model:value="formState.sort" style="width: 100%;" />
                    </a-form-item>

                    <a-form-item v-if="quickReplyType == 'phrase'" :label="$t('所属分组')">
                        <span>{{quickReplyNavList[1].list[quickReplyleftBarIndex].text}}</span>
                    </a-form-item>

                    <a-form-item v-if="quickReplyType == 'phrase'" :label="$t('短语内容')" name="context" :rules="[{ required: true, message: $t('请填写短语内容') }]">
                        <a-textarea v-model:value="formState.context" :placeholder="$t('请填写短语内容')" :rows="4" />
                    </a-form-item>

                    <a-form-item v-else-if="quickReplyType == 'phraseGrouping'" :label="$t('分组名称')" name="context" :rules="[{ required: true, message: $t('请填写分组名称') }]">
                        <a-input v-model:value="formState.context" :placeholder="$t('请填写分组名称')" />
                    </a-form-item>
                </a-form>
            </div>
            <!-- 优惠券 -->
            <div v-else-if="modalType == 'kf_coupon'" class="coupon-box mt-15 mb-15 scrollbar">
                <EasySpin :spinning="easySpinning" :tip="tip" />
                <a-radio-group v-model:value="selectValue" v-if="kfCouponList.length > 0">
                    <a-radio :value="item" v-for="(item, index) in kfCouponList" :key="item.coupon_id">
                        <div class="coupon-item">
                            <div class="content1 flex flex-col justify-center align-center">
                                <div class="price">
                                    <span class="fs-14">￥</span>
                                    <span class="fs-18">{{item.discount}}</span>
                                </div>
                                <div class="fs-14">{{$t('满')}}{{item.order_money}}{{$t('元可用')}}</div>
                            </div>
                            <div class="content2">
                                <div class="title text-ellipsis">{{item.name}}</div>
                                <div class="desc">{{$t('有效期')}}：{{item.start_time}} {{$t('至')}} {{item.end_time}}</div>
                                <div class="desc">{{item.platform.join('、')}}</div>
                            </div>
                        </div>
                    </a-radio>
                </a-radio-group>
                <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                    <a-empty :description="$t('暂无优惠券')" :image="simpleImage" />
                </div>
            </div>
            <!-- 推荐商品 -->
            <template v-else-if="modalType == 'recommend_goods'">
                <EasySpin :spinning="easySpinning" :tip="tip" />
                <a-tabs v-model:activeKey="recommendGoodsParams.type" @change="tabsChange">
                    <a-tab-pane key="mall" :tab="$t('商城')"></a-tab-pane>
                    <a-tab-pane key="shop" :tab="$t('外卖')"></a-tab-pane>
                    <a-tab-pane key="group" :tab="$t('团购')"></a-tab-pane>
                </a-tabs>
                <div class="coupon-box goods-box scrollbar" @scroll="recommendGoodsScroll">
                    <a-radio-group v-model:value="selectValue" v-if="recommendGoods.length > 0">
                        <a-radio :value="item" v-for="(item, index) in recommendGoods" :key="item.id">
                            <div class="coupon-item">
                                <div class="content1 flex flex-col justify-center align-center">
                                    <img v-lazy="item.image" class="goods-img" />
                                </div>
                                <div class="content2">
                                    <div class="title text-ellipsis">{{item.name}}</div>
                                    <div class="flex align-center mt-10">
                                        <span class="price mr-20">￥{{item.price}}</span>
                                        <span class="count">x{{item.sale_count}}人付款</span>
                                    </div>
                                </div>
                            </div>
                        </a-radio>
                        <div class="more flex align-center justify-center fs-14 mb-30">
                            <Loadmore :status="loadStatus" />
                        </div>
                    </a-radio-group>
                    <div class="flex align-center justify-center" style="width: 100%;height: 100%;" v-else>
                        <a-empty :description="$t('暂无商品')" :image="simpleImage" />
                    </div>
                </div>
            </template>
        </a-modal>
    </div>
</template>

<script setup>
import { defineComponent, reactive, ref, getCurrentInstance, computed, onMounted, toRefs, nextTick } from 'vue'
import { PlusOutlined } from '@ant-design/icons-vue'
import emojiJSON from '@/common/utils/emoji.json'
import utils from '@/common/utils/utils'
import { useStore } from 'vuex'
import { Empty } from 'ant-design-vue'
const simpleImage = Empty.PRESENTED_IMAGE_SIMPLE
const store = useStore()
const emits = defineEmits(['actionsCallBack'])
const props = defineProps({
    toUserInfo: {
        type: Object,
        default: {},
    },
})
const state = reactive({
    transferKFVisible: false,
    quickReplyVisible: false,
    kfValue: '',
    kfList: [], //客服列表
    quickReplyNavList: [
        {
            name: window.$t('团队'),
            value: 'personal_phrases',
            list: [],
        },
        {
            name: window.$t('个人'),
            value: 'store_phrases',
            ist: [],
        },
    ],
    quickReplyNavIndex: 0,
    quickReplyleftBarIndex: 0,
    modalOpen: false,
    modalType: '',
    quickReplyType: '',
    modelTitle: '添加快捷短语',
    form: null,
    selectValue: '',
    emojiOpen: false,
    uploadAction: '',
    uploadName: '',
    uploadData: {},
    easySpinning: false,
    tip: window.$t('加载中...'),
    confirmLoading: false,
    kfCouponList: [],
    recommendGoods: [],
    recommendGoodsParams: {
        page: 1,
        page_size: 10,
        type: 'mall',
    },
    loadStatus: 'loadmore', //加载更多
    operateList: [], //操作权限列表
})
const formState = reactive({
    context: '',
    group_id: '',
    sort: 0,
    id: '',
})
const {
    transferKFVisible,
    quickReplyVisible,
    kfValue,
    kfList,
    quickReplyNavIndex,
    quickReplyNavList,
    quickReplyleftBarIndex,
    modelTitle,
    modalOpen,
    form,
    modalType,
    quickReplyType,
    selectValue,
    emojiOpen,
    uploadAction,
    uploadName,
    uploadData,
    easySpinning,
    tip,
    confirmLoading,
    kfCouponList,
    recommendGoods,
    recommendGoodsParams,
    loadStatus,
} = toRefs(state)

const operate = () => {
    window.$request
        .post('/im/User/operate')
        .then((res) => {
            state.operateList = res
        })
        .catch((err) => {})
}
operate()

//头部导航切换
const navClick = (item, index) => {
    state.quickReplyleftBarIndex = 0
    state.quickReplyNavIndex = index
    actionsClick('quick_reply')
}
//侧边栏导航切换
const navLeftBarClick = (item, index) => {
    state.quickReplyleftBarIndex = index
}
//右侧内容点击
const navRightBarClick = (item) => {
    emits('actionsCallBack', 'quickReplyCallBack', item.text)
}
//添加短语事件
const addQuickReply = (type) => {
    state.modalType = 'quickReply'
    state.quickReplyType = type
    state.quickReplyVisible = false
    if (type == 'phrase') {
        state.modelTitle = window.$t('添加快捷短语')
    } else if (type == 'phraseGrouping') {
        state.modelTitle = window.$t('添加快捷短语分组')
    }
    formState.context = ''
    formState.group_id = ''
    formState.sort = 0
    formState.id = ''
    state.modalOpen = true
}
//商品类型切换
const tabsChange = (e) => {
    state.recommendGoodsParams.page = 1
    actionsClick('recommend_goods')
}
//弹窗确定事件
const handleOk = () => {
    if (state.modalType == 'quickReply') {
        state.form
            .validateFields()
            .then((values) => {
                let params = formState
                if (state.quickReplyType == 'phrase') {
                    formState.group_id = state.quickReplyNavList[1].list[state.quickReplyleftBarIndex].id
                } else {
                    params = {
                        name: values.context,
                        sort: values.sort,
                        id: formState.id,
                    }
                }
                //个人短语
                state.confirmLoading = true
                window.$request
                    .post(state.quickReplyType == 'phrase' ? '/im/QuickReply/savePharse' : '/im/QuickReply/savePharseGroup', params)
                    .then((res) => {
                        state.confirmLoading = false
                        state.modalOpen = false
                        state.quickReplyVisible = true
                        window.$message.success(window.$t(formState.id ? '编辑成功' : '添加成功'))
                        actionsClick('quick_reply')
                    })
                    .catch((err) => {
                        state.confirmLoading = false
                    })
            })
            .catch((info) => {})
    } else if (state.modalType == 'kf_coupon') {
        if (!state.selectValue) {
            window.$message.info(window.$t('请选择优惠券'))
            return
        }
        emits('actionsCallBack', 'kf_coupon', {
            type: 'kf_coupon',
            coupon: state.selectValue,
        })
        state.modalOpen = false
    } else if (state.modalType == 'recommend_goods') {
        if (!state.selectValue) {
            window.$message.info(window.$t('请选择商品'))
            return
        }
        emits('actionsCallBack', 'recommend_goods', {
            type: 'recommend_goods',
            goods: state.selectValue,
        })
        state.modalOpen = false
    }
}

//快捷回复的分组以及快捷语右键的事件
const itemMenuClick = (event, type, item) => {
    if (event.key == 'edit') {
        formState.sort = item.sort
        formState.context = item.text
        formState.id = item.id
        if (type == 'phrase') {
            formState.group_id = item.id
        }
        state.quickReplyVisible = false
        state.modalType = 'quickReply'
        state.quickReplyType = type
        state.modalOpen = true
    } else if (event.key == 'delete') {
        if (type == 'phrase') {
            //快捷回复
            window.$request
                .post('/im/QuickReply/delPharse', { id: item.id })
                .then((res) => {
                    window.$message.success(window.$t('删除成功'))
                    actionsClick('quick_reply')
                })
                .catch((err) => {})
        } else if (type == 'phraseGrouping') {
            //个人分组
            window.$request
                .post('/im/QuickReply/delPharseGroup', { id: item.id })
                .then((res) => {
                    state.quickReplyleftBarIndex = 0
                    window.$message.success(window.$t('删除成功'))
                    actionsClick('quick_reply')
                })
                .catch((err) => {})
        }
    }
}

const cancel = () => {
    if (state.modalType == 'quickReply') {
        state.quickReplyVisible = true
    }
}
//上传是图片或者视频
const beforeUpload = (file) => {
    // 判断文件类型
    const isImage = file.type.startsWith('image/')
    const isVideo = file.type.startsWith('video/')
    // 根据文件类型设置不同的大小限制
    let maxSize
    if (isImage) {
        state.uploadAction = `${
            process.env.NODE_ENV === 'development' ? 'api' : ''
        }/v20/public/index.php/common/common.UploadFile/uploadPic`
        state.uploadName = 'pic'
        state.uploadData = {
            type: '/customer_service/image',
        }
        maxSize = 100 // 图片最大100MB
    } else if (isVideo) {
        state.uploadAction = `${
            process.env.NODE_ENV === 'development' ? 'api' : ''
        }/v20/public/index.php/common/common.UploadFile/uploadVideos`
        state.uploadName = 'video'
        state.uploadData = {
            upload_dir: '/customer_service/video',
        }
        maxSize = 10 // 视频最大10MB
    }

    // 判断文件大小是否符合要求
    const isLtMaxSize = file.size / 1024 / 1024 < maxSize

    if (!isLtMaxSize) {
        window.$message.error(`文件必须小于${maxSize}MB！`)
        return false // 返回 false 可以阻止上传
    }

    return isImage || isVideo
}
const handleChange = (info) => {
    if (info.file.status == 'uploading') {
        window.$Bus.emit('chatRoomCallBack', { type: 'uploadFile', data: true })
    }
    if (info.file.status === 'done') {
        window.$Bus.emit('chatRoomCallBack', { type: 'uploadFile', data: false })
        const { data,status,msg } = info.file.response
        const isImage = info.file.type.startsWith('image/')
        const isVideo = info.file.type.startsWith('video/')
        if(status == 1003){
            window.$message.error(`${msg}`)
            return
        }
        if (isImage) {
            emits('actionsCallBack', 'uploadFile', {
                type: 'image',
                url: data.url,
            })
        } else if (isVideo) {
            emits('actionsCallBack', 'uploadFile', {
                type: 'video',
                url: data.video_full_url,
                thunm: data.image_full_url,
            })
        }
    } else if (info.file.status === 'error') {
        window.$Bus.emit('chatRoomCallBack', { type: 'uploadFile', data: false })
        window.$message.error(`${info.file.name} 文件上传失败.`)
    }
}
//点击表情事件
const showEmoji = (item) => {
    item && emits('actionsCallBack', 'showEmoji', item)
}

const actionsClick = async (type, resetting) => {
    state.easySpinning = true
    state.tip = window.$t('加载中...')
    switch (type) {
        case 'kefu':
            state.kfValue = ''
            await utils.sleep(300)
            window.$request.post('/im/User/kfLists').then((res) => {
                state.kfList = res
                state.easySpinning = false
            })
            break
        case 'quick_reply':
            await utils.sleep(300)
            window.$request.post('/im/QuickReply/lists').then((res) => {
                state.quickReplyNavList[0].list = res.store_phrases
                state.quickReplyNavList[1].list = res.personal_phrases
                state.easySpinning = false
                if (resetting == true) {
                    state.quickReplyleftBarIndex = 0
                }
            })
            break
        case 'kf_coupon':
            state.modalType = 'kf_coupon'
            state.modelTitle = window.$t('选择优惠券')
            state.selectValue = ''
            state.modalOpen = true
            window.$request.post('/im/user/getKfCoupon').then((res) => {
                state.kfCouponList = res
                state.easySpinning = false
            })
            break
        case 'recommend_goods':
            state.modalType = 'recommend_goods'
            state.modelTitle = window.$t('推荐商品')
            state.selectValue = ''
            state.modalOpen = true
            state.recommendGoodsParams.page = 1
            state.loadStatus = 'loading'
            state.recommendGoods = []
            getRecommendGoodsList()
            break
        default:
            break
    }
}
const kfConfirm = () => {
    if (state.kfValue) {
        state.easySpinning = true
        state.tip = window.$t('转接中...')
        let params = {
            from_kf: store.state.user.userInfo.username,
            to_kf: state.kfValue,
            customer: props.toUserInfo.username,
        }
        window.$request
            .post('/im/User/transferKf', params)
            .then((res) => {
                state.easySpinning = false
                state.transferKFVisible = false
                emits('actionsCallBack', 'transferKf')
                window.$message.success(window.$t('转接成功'))
            })
            .catch((err) => {
                state.easySpinning = false
            })
    }
}

const getRecommendGoodsList = () => {
    state.loadStatus = 'loading'
    window.$request.post('/im/user/recommendGoods', state.recommendGoodsParams).then((res) => {
        state.recommendGoods = [...state.recommendGoods, ...res]
        if (res.length < 10) {
            state.loadStatus = 'nomore'
        } else {
            state.loadStatus = 'loadmore'
        }
        state.easySpinning = false
    })
}

const recommendGoodsScroll = (e) => {
    const element = e.target
    if (element.scrollHeight - element.scrollTop <= element.clientHeight) {
        if (state.loadStatus != 'nomore' && state.loadStatus != 'loading') {
            // 在这里可以触发加载更多数据的操作或其他逻辑
            state.recommendGoodsParams.page++
            getRecommendGoodsList()
        }
    }
}
