/*组件按需引入*/

import {
  Button,
  Divider,
  Form,
  Input,
  InputNumber,
  ConfigProvider,
  Select,
  Popover,
  Dropdown,
  Menu,
  message,
  Drawer,
  Image,
  Carousel,
  Timeline,
  Modal,
  Avatar,
  Spin,
  Slider,
  Switch,
  Checkbox,
  List,
  Upload,
  Empty,
  FloatButton,
  Skeleton,
  Qrcode,
  Statistic,
  Tooltip,
  Radio,
  Tabs,
  Badge,
  Popconfirm,
  Result,
} from "ant-design-vue";
import EasySpin from "@/components/EasySpin";
import Loadmore from "@/components/Loadmore";

import utils from "./utils";
import request from "./request";
import { createFromIconfontCN } from "@ant-design/icons-vue";
const IconFont = createFromIconfontCN({
  scriptUrl: "//at.alicdn.com/t/c/font_4086553_sykfaza63a.js",
});
const appUse = (app) => {
  app.use(Button);
  app.use(Divider);
  app.use(Form);
  app.use(Input);
  app.use(ConfigProvider);
  app.use(Select);
  app.use(Popover);
  app.use(Dropdown);
  app.use(Menu);
  app.use(Drawer);
  app.use(Image);
  app.use(Carousel);
  app.use(Timeline);
  app.use(Modal);
  app.use(Avatar);
  app.use(Spin);
  app.use(Slider);
  app.use(Switch);
  app.use(Checkbox);
  app.use(List);
  app.use(Upload);
  app.use(Empty);
  app.use(FloatButton);
  app.use(Skeleton);
  app.use(Qrcode);
  app.use(Statistic);
  app.use(Tooltip);
  app.use(Radio);
  app.use(Tabs);
  app.use(Badge);
  app.use(InputNumber);
  app.use(Popconfirm);
  app.use(Result);
  
  app.component("EasySpin", EasySpin);
  app.component("Loadmore", Loadmore);
  app.config.globalProperties.$message = message;
  app.config.globalProperties.$Modal = Modal;
  app.config.globalProperties.$utils = utils;
  app.config.globalProperties.$request = request;
  window.$message = message;
  window.$Modal = Modal;
  window.$request = request;
};

export default appUse;
