<template>
    <a-result :status="status" :title="status" :sub-title="$t('抱歉，您无权访问此页面。')">
        <template #extra>
            <a-button type="primary" @click="backHome">{{$t('回到首页')}}</a-button>
        </template>
    </a-result>
</template>

<script setup>
import { ref, toRefs } from 'vue'
import { useRoute, useRouter } from 'vue-router'
const route = useRoute()
const router = useRouter()
const status = ref(route.query.status || 404)
const backHome = ()=>{
    router.replace('/chat')
}
</script>
